/* notification center */
.notification-center{position:relative}
.notification-bell-wrap{position:relative}
.notification-badge{position:absolute;right:-3px;top:-4px;min-width:17px;height:17px;padding:0 4px;border-radius:999px;background:var(--danger);color:#fff;border:2px solid var(--surface);display:grid;place-items:center;font-size:8px;font-weight:900;line-height:1;pointer-events:none}
.notification-panel{position:absolute;right:-54px;top:calc(100% + 12px);width:min(410px,calc(100vw - 24px));max-height:min(620px,calc(100dvh - 92px));background:var(--surface);border:1px solid var(--border);border-radius:20px;box-shadow:0 26px 80px rgba(14,24,42,.22);overflow:hidden;display:flex;flex-direction:column;z-index:160}
.notification-panel__head{padding:15px 15px 12px 17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}
.notification-panel__head>div{display:flex;flex-direction:column}
.notification-panel__head strong{font-size:15px}
.notification-panel__head span{font-size:9px;color:var(--muted);margin-top:2px}
.notification-panel__toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 12px;border-bottom:1px solid var(--border);background:var(--surface2)}
.notification-filter{display:flex;gap:3px;background:var(--surface3);padding:3px;border-radius:10px}
.notification-filter button{border:0;background:transparent;min-height:28px;padding:0 9px;border-radius:8px;font-size:9px;font-weight:850;color:var(--muted)}
.notification-filter button.is-active{background:var(--surface);color:var(--text);box-shadow:0 1px 3px rgba(0,0,0,.06)}
.notification-mark-all{border:0;background:transparent;color:var(--accent);font-size:9px;font-weight:850;padding:6px}
.notification-list{overflow:auto;overscroll-behavior:contain}
.notification-item{width:100%;border:0;border-bottom:1px solid var(--border);background:var(--surface);display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:start;padding:12px 13px;text-align:left}
.notification-item:hover{background:var(--surface2)}
.notification-item.is-unread{background:color-mix(in srgb,var(--accent) 4%,var(--surface))}
.notification-item__icon{width:36px;height:36px;border-radius:12px;display:grid;place-items:center;color:var(--accent);background:color-mix(in srgb,var(--accent) 9%,var(--surface))}
.notification-item__icon--deadline{color:var(--warning);background:color-mix(in srgb,var(--warning) 9%,var(--surface))}
.notification-item__icon--chore{color:#7c3aed;background:color-mix(in srgb,#7c3aed 8%,var(--surface))}
.notification-item__icon--stock{color:var(--success);background:color-mix(in srgb,var(--success) 8%,var(--surface))}
.notification-item__icon--system{color:var(--danger);background:color-mix(in srgb,var(--danger) 8%,var(--surface))}
.notification-item__icon--update{color:#2563eb;background:color-mix(in srgb,#2563eb 8%,var(--surface))}
.notification-item__copy{display:flex;flex-direction:column;min-width:0;padding-top:1px}
.notification-item__title{font-size:10px;font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.notification-item__detail{font-size:9px;color:var(--muted);line-height:1.4;margin-top:3px}
.notification-item__meta{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:8px;white-space:nowrap;padding-top:2px}
.notification-item__meta i{width:7px;height:7px;border-radius:50%;background:var(--accent)}
.notification-empty{min-height:220px;padding:30px 24px;display:flex;align-items:center;justify-content:center;text-align:center;flex-direction:column;color:var(--muted)}
.notification-empty svg{color:var(--accent);margin-bottom:9px}
.notification-empty strong{font-size:12px;color:var(--text)}
.notification-empty span{font-size:9px;line-height:1.5;max-width:270px;margin-top:4px}

@media(max-width:820px){
  .notification-panel{position:fixed;left:10px;right:10px;top:calc(var(--topbar) + env(safe-area-inset-top) + 8px);width:auto;max-height:calc(100dvh - var(--topbar) - var(--bottom) - env(safe-area-inset-top) - env(safe-area-inset-bottom) - 24px);border-radius:18px}
}
@media(max-width:520px){
  .notification-panel__toolbar{align-items:flex-start;flex-direction:column}
  .notification-filter{width:100%}
  .notification-filter button{flex:1}
  .notification-mark-all{align-self:flex-end}
  .notification-item{padding:11px}
}

@media(max-width:520px){.weekday-picker{grid-template-columns:repeat(4,1fr)}.recurring-row{grid-template-columns:auto minmax(0,1fr) auto auto}.recurring-row>.badge{display:none}}

/* chore approval workflow */
.approval-banner{display:flex;align-items:center;gap:10px;margin:-6px 0 16px;padding:12px 14px;border:1px solid color-mix(in srgb,var(--warning) 24%,var(--border));border-radius:14px;background:color-mix(in srgb,var(--warning) 7%,var(--surface));color:var(--warning)}
.approval-banner>div{display:flex;flex-direction:column;gap:2px}
.approval-banner strong{font-size:11px}
.approval-banner span{font-size:9px;color:var(--muted)}
.chore-item--pending{background:color-mix(in srgb,var(--warning) 5%,var(--surface));border-radius:12px;padding-left:7px;padding-right:5px}
.chore-item--pending .check-item__check{border-color:color-mix(in srgb,var(--warning) 45%,var(--border2));color:var(--warning);background:color-mix(in srgb,var(--warning) 8%,var(--surface))}
.chore-status{display:block;font-size:8px!important;font-weight:800;margin-top:4px!important}
.chore-status--pending{color:var(--warning)!important}
.chore-status--approved{color:var(--success)!important}
.chore-status--open{color:var(--muted)!important}
.chore-approval-actions{display:flex;align-items:center;gap:4px}
.wallet-card__head small{font-size:8px;color:var(--muted);margin-top:3px;line-height:1.35}
.check-item__copy:disabled{cursor:default;opacity:1}
.check-item__check:disabled{cursor:default}
@media(max-width:520px){.chore-item--pending{grid-template-columns:auto minmax(0,1fr);gap:7px}.chore-item--pending .chore-approval-actions{grid-column:2;justify-content:flex-start;padding-bottom:8px}.chore-item--pending>.icon-btn{grid-column:2}}

/* family routines */
.todo-routine-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.routine-list{display:flex;flex-direction:column}
.routine-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto auto auto;align-items:center;gap:8px;min-height:70px;border-bottom:1px solid var(--border)}
.routine-row:last-child{border-bottom:0}
.routine-row.is-disabled{opacity:.56}
.routine-row__copy{border:0;background:transparent;text-align:left;display:flex;flex-direction:column;gap:3px;min-width:0;padding:10px 0}
.routine-row__copy:disabled{opacity:1;cursor:default}
.routine-row__copy strong{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.routine-row__copy span,.routine-row__copy small{display:flex;align-items:center;gap:5px;font-size:9px;color:var(--muted)}
.routine-row__copy em{font-size:8px;color:var(--faint);font-style:normal;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.routine-due-item small{display:block;font-size:8px;color:var(--muted);margin-top:3px}
.routine-history-copy{cursor:default}
.routine-history-copy span{display:flex!important;align-items:center;gap:5px}
@media(max-width:900px){.todo-routine-grid{grid-template-columns:1fr}}
@media(max-width:520px){.routine-row{grid-template-columns:auto minmax(0,1fr) auto}.routine-row>.badge{display:none}.routine-row>.icon-btn:last-child{grid-column:3}}

/* smart annual deadline center */
.deadline-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:14px}
.deadline-stat{padding:14px 16px;display:flex;flex-direction:column;gap:3px}
.deadline-stat span{font-size:9px;font-weight:800;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.deadline-stat strong{font-size:24px;line-height:1}
.deadline-stat small{font-size:8px;color:var(--faint)}
.deadline-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}
.deadline-category-filter{display:flex;align-items:center;gap:5px;overflow:auto;padding:2px;scrollbar-width:none}
.deadline-category-filter::-webkit-scrollbar{display:none}
.deadline-category-filter button{border:1px solid var(--border);background:var(--surface);border-radius:999px;min-height:31px;padding:0 9px;display:flex;align-items:center;gap:5px;color:var(--muted);font-size:8px;font-weight:800;white-space:nowrap}
.deadline-category-filter button.is-active{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 9%,var(--surface));color:var(--accent)}
.deadline-copy--smart small{display:block;font-size:8px;color:var(--muted);margin-top:3px}
.deadline-copy--smart em{display:block;font-size:8px;color:var(--faint);font-style:normal;margin-top:3px;max-width:520px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.deadline-row--overdue{background:color-mix(in srgb,var(--danger) 5%,var(--surface));border-radius:12px;padding-left:7px;padding-right:5px}
.deadline-row--today{background:color-mix(in srgb,var(--warning) 7%,var(--surface));border-radius:12px;padding-left:7px;padding-right:5px}
.deadline-row--soon{background:color-mix(in srgb,var(--accent) 3%,var(--surface))}
.deadline-reminder-picker{display:flex;flex-wrap:wrap;gap:7px}
.deadline-reminder-picker button{min-height:34px;border:1px solid var(--border);background:var(--surface);border-radius:999px;padding:0 11px;font-size:9px;font-weight:800;color:var(--muted)}
.deadline-reminder-picker button.is-active{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 9%,var(--surface));color:var(--accent)}
.deadline-last-completed{display:flex;align-items:center;gap:7px;padding:10px 12px;border-radius:10px;background:var(--surface2);font-size:9px;color:var(--muted)}
.year-deadline-view{display:flex;flex-direction:column;gap:12px}
.year-deadline-head{display:flex;align-items:center;justify-content:center;gap:12px}
.year-deadline-head>div{min-width:140px;text-align:center;display:flex;flex-direction:column}
.year-deadline-head span{font-size:8px;color:var(--muted);text-transform:uppercase;font-weight:800}
.year-deadline-head strong{font-size:24px}
.year-deadline-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.year-month-card{min-height:165px;padding:12px}
.year-month-card>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.year-month-card>header>span{font-size:11px;font-weight:850;text-transform:capitalize}
.year-month-list{display:flex;flex-direction:column;gap:4px}
