/* Cloud auth / family onboarding */
.auth-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
  margin: -18px 0 24px;
  padding: 4px;
  border-radius: 13px;
  background: var(--surface-3);
}

.auth-tabs button {
  min-height: 38px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 11px;
  font-weight: 800;
}

.auth-tabs button.is-active {
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 1px 4px rgba(0, 0, 0, .08);
}

.demo-access { margin-top: 18px; text-align: center; }
.demo-access .login-users { text-align: left; }

.login-screen--loading {
  display: grid;
  grid-template-columns: 1fr;
  place-items: center;
  background: var(--bg);
}

.cloud-loader {
  min-width: 220px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
}

.cloud-loader .brand-mark { margin-bottom: 12px; }
.cloud-loader strong { font-size: 17px; }
.cloud-loader > span:last-child { color: var(--muted); font-size: 11px; }

.cloud-loader__ring {
  width: 28px;
  height: 28px;
  margin-top: -2px;
  border: 3px solid var(--surface-3);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: cloud-spin .8s linear infinite;
}

@keyframes cloud-spin { to { transform: rotate(360deg); } }
.spin { animation: cloud-spin .9s linear infinite; }

.family-setup-screen {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 28px;
  background:
    radial-gradient(circle at 20% 5%, color-mix(in srgb, var(--accent) 12%, transparent), transparent 34%),
    var(--bg);
}

.family-setup-card {
  width: min(540px, 100%);
  padding: 28px;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: var(--surface);
  box-shadow: var(--shadow-md);
}

.family-setup-card .login-brand { margin-bottom: 28px; }
.family-setup-card .auth-tabs { margin: 22px 0 18px; }

.setup-hero {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.setup-hero > svg {
  width: 48px;
  height: 48px;
  padding: 12px;
  border-radius: 15px;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
}

.setup-hero h2 {
  margin: 14px 0 7px;
  font-size: 25px;
  line-height: 1.08;
  letter-spacing: -.035em;
}

.setup-hero p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.55;
}

.setup-form { display: flex; flex-direction: column; gap: 14px; }

.toggle-row--boxed {
  align-items: flex-start;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface-2);
  cursor: pointer;
}

.toggle-row--boxed > span {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.toggle-row--boxed strong { color: var(--text); font-size: 11px; }
.toggle-row--boxed small { color: var(--muted); font-size: 9px; line-height: 1.45; }

.setup-logout {
  width: 100%;
  min-height: 40px;
  margin-top: 18px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 800;
}

.setup-logout:hover { background: var(--surface-2); color: var(--text); }

.sync-indicator {
  min-height: 30px;
  width: fit-content;
  max-width: 160px;
  padding: 5px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 800;
}

button.sync-indicator { cursor: pointer; }
.sync-indicator--synced { color: var(--success); border-color: color-mix(in srgb, var(--success) 18%, var(--border)); background: color-mix(in srgb, var(--success) 6%, var(--surface)); }
.sync-indicator--saving, .sync-indicator--connecting, .sync-indicator--conflict { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 18%, var(--border)); background: color-mix(in srgb, var(--accent) 6%, var(--surface)); }
.sync-indicator--error { color: var(--danger); border-color: color-mix(in srgb, var(--danger) 18%, var(--border)); background: color-mix(in srgb, var(--danger) 6%, var(--surface)); }
.sync-indicator--offline { color: var(--faint); }

.sidebar__footer > .sync-indicator { margin: 0 8px 5px; }
.mobile-more__status { display: flex; justify-content: center; padding: 0 0 10px; }

.invite-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface-2);
}

.invite-panel__copy { min-width: 0; flex: 1 1 220px; }
.invite-panel__copy strong { display: block; font-size: 11px; }
.invite-panel__copy span { display: block; margin-top: 3px; color: var(--muted); font-size: 9px; }
.invite-code {
  padding: 8px 11px;
  border-radius: 10px;
  background: var(--surface);
  border: 1px dashed color-mix(in srgb, var(--accent) 35%, var(--border));
  color: var(--accent);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: .08em;
}

@media (max-width: 820px) {
  .topbar__right > .sync-indicator { max-width: 34px; width: 34px; height: 34px; padding: 0; justify-content: center; }
  .topbar__right > .sync-indicator span, .topbar__right > .sync-indicator .spin { display: none; }
  .family-setup-screen { padding: max(18px, env(safe-area-inset-top)) 14px max(18px, env(safe-area-inset-bottom)); }
  .family-setup-card { padding: 20px; border-radius: 21px; }
}

@media (max-width: 520px) {
  .family-setup-screen { align-items: stretch; padding: 0; background: var(--surface); }
  .family-setup-card { width: 100%; min-height: 100dvh; padding: max(24px, env(safe-area-inset-top)) 18px max(20px, env(safe-area-inset-bottom)); border: 0; border-radius: 0; box-shadow: none; }
  .setup-hero h2 { font-size: 23px; }
  .auth-tabs { margin-top: 18px; }
  .invite-panel { align-items: stretch; }
  .invite-code { width: 100%; text-align: center; }
}

