/* Responsive hardening layer
   Loaded after app.css so the UI adapts to narrow in-app browsers, Safari,
   standalone PWA mode, tablets and landscape without allowing page-level overflow. */

html,
body,
#root,
.app-shell,
.app-main,
.content,
.page {
  min-width: 0;
  max-width: 100%;
}

html,
body,
#root {
  overflow-x: hidden;
}

body {
  width: 100%;
  max-width: 100vw;
  overscroll-behavior-x: none;
}

.app-shell,
.app-main,
.content {
  width: 100%;
  overflow-x: hidden;
}

.page,
.card,
.card-header,
.page-intro,
.quick-actions,
.stats-grid,
.dashboard-grid,
.calendar-card,
.shopping-layout,
.scan-layout,
.wallet-layout,
.settings-grid,
.chores-grid,
.users-grid,
.pantry-grid,
.dish-grid {
  min-width: 0;
}

button,
input,
select,
textarea,
.list-row__content,
.card-header__copy,
.page-intro__copy {
  min-width: 0;
}

/* Internal horizontal scrollers must never drag the whole page sideways. */
.chip-scroll,
.week-strip,
.meal-planner-card,
.segmented {
  max-width: 100%;
  overscroll-behavior-x: contain;
  -webkit-overflow-scrolling: touch;
}

@supports (height: 100svh) {
  .app-shell,
  .app-main,
  .sidebar,
  .login-screen {
    min-height: 100svh;
  }
}

@media (max-width: 820px) {
  :root {
    --topbar: 58px;
    --bottom: 68px;
  }

  .app-shell,
  .app-main {
    height: 100dvh;
    max-height: 100dvh;
  }

  .content {
    width: 100%;
    padding-top: 14px;
    padding-right: max(10px, env(safe-area-inset-right));
    padding-left: max(10px, env(safe-area-inset-left));
    padding-bottom: calc(var(--bottom) + 18px + env(safe-area-inset-bottom));
    scrollbar-width: none;
  }

  .content::-webkit-scrollbar,
  .quick-actions::-webkit-scrollbar,
  .week-strip::-webkit-scrollbar,
  .chip-scroll::-webkit-scrollbar {
    display: none;
  }

  .topbar {
    width: 100%;
    min-width: 0;
    padding-right: max(10px, env(safe-area-inset-right));
    padding-left: max(10px, env(safe-area-inset-left));
  }

  .topbar__left,
  .topbar__right {
    min-width: 0;
  }

  .topbar__left > div:last-child {
    min-width: 0;
  }

  .topbar__left > div:last-child > span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .page-intro {
    width: 100%;
    gap: 10px;
    margin-bottom: 14px;
  }

  .page-intro__copy {
    flex: 1 1 auto;
  }

  .page-intro h1 {
    font-size: clamp(24px, 7vw, 30px);
  }

  .page-intro p {
    max-width: 100%;
    font-size: 11px;
  }

  .page-intro__actions {
    flex: 0 0 auto;
  }

  /* Home: no carousel that can leave the page horizontally scrolled. */
  .quick-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 7px;
    width: 100%;
    overflow: visible;
    margin-bottom: 10px;
  }

  .quick-actions button {
    width: 100%;
    min-width: 0;
    min-height: 42px;
    padding: 0 9px;
    justify-content: flex-start;
  }

  .quick-actions button span {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    width: 100%;
  }

  .stat-card {
    width: 100%;
    min-width: 0;
    min-height: 126px;
    padding: 13px;
  }

  .stat-card small {
    white-space: normal;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .dashboard-grid {
    grid-template-columns: minmax(0, 1fr);
    width: 100%;
  }

  .dashboard-card,
  .dashboard-card--wide,
  .dashboard-card--full {
    grid-column: auto;
    width: 100%;
  }

  .week-strip {
    display: flex;
    gap: 7px;
    width: 100%;
    overflow-x: auto;
    scroll-snap-type: x proximity;
    padding-bottom: 2px;
  }

  .week-day {
    flex: 0 0 min(42vw, 145px);
    min-width: 112px;
    scroll-snap-align: start;
  }

  /* Calendar: month view always fits the actual viewport. */
  .calendar-card {
    width: 100%;
    max-width: 100%;
  }

  .calendar-toolbar {
    width: 100%;
    padding: 10px;
    gap: 8px;
  }

  .calendar-toolbar__nav {
    width: 100%;
    display: grid;
    grid-template-columns: 36px auto 36px minmax(0, 1fr);
    gap: 4px;
  }

  .calendar-toolbar__nav .icon-btn {
    width: 36px;
    height: 36px;
  }

  .calendar-toolbar__nav h2 {
    min-width: 0;
    margin-left: 2px;
    font-size: 13px;
    text-align: right;
  }

  .today-btn {
    min-width: 0;
    padding: 0 8px;
  }

  .calendar-toolbar > .segmented {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    overflow: hidden;
  }

  .calendar-toolbar > .segmented button {
    width: 100%;
    min-width: 0;
    padding: 0 5px;
  }

  .month-view {
    width: 100%;
    max-width: 100%;
    overflow: hidden;
  }

  .month-head,
  .month-grid {
    width: 100%;
    min-width: 0;
    grid-template-columns: repeat(7, minmax(0, 1fr));
  }

  .month-head > div {
    min-width: 0;
    padding: 7px 0;
    font-size: 8px;
  }

  .month-cell {
    min-width: 0;
    min-height: 82px;
    padding: 3px 2px;
    overflow: hidden;
  }

  .month-cell__day {
    width: 26px;
    height: 26px;
    font-size: 10px;
  }

  .month-cell__events {
    min-width: 0;
    gap: 2px;
    margin-top: 2px;
  }

  .calendar-event {
    width: 100%;
    min-width: 0;
    padding: 3px;
    border-left-width: 2px;
    display: block;
    overflow: hidden;
  }

  .calendar-event span {
    display: none;
  }

  .calendar-event strong {
    display: block;
    width: 100%;
    font-size: 7px;
    line-height: 1.15;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .calendar-more {
    display: block;
    max-width: 100%;
    padding-left: 2px;
    font-size: 7px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Week becomes a vertical, phone-friendly agenda instead of a 980px board. */
  .week-calendar {
    width: 100%;
    min-width: 0;
    display: flex;
    flex-direction: column;
    overflow: visible;
  }

  .week-calendar__day {
    width: 100%;
    min-height: 0;
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .week-calendar__head {
    position: sticky;
    top: 0;
    z-index: 1;
  }

  .week-calendar__events {
    padding: 7px 8px 10px;
  }

  .week-event {
    width: 100%;
  }

  .agenda-list {
    width: 100%;
    padding: 4px 8px;
  }

  .agenda-row {
    width: 100%;
    min-width: 0;
    grid-template-columns: 36px 38px minmax(0, 1fr) 16px;
    gap: 6px;
    padding: 9px 1px;
  }

  .agenda-user {
    display: none;
  }

  /* Shopping / pantry */
  .shopping-layout,
  .scan-layout,
  .settings-grid,
  .chores-grid {
    grid-template-columns: minmax(0, 1fr);
    width: 100%;
  }

  .quick-input-row {
    width: 100%;
    grid-template-columns: minmax(0, 1fr) 60px 64px 42px;
    gap: 5px;
  }

  .pantry-toolbar {
    width: 100%;
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .pantry-toolbar .chip-scroll {
    width: 100%;
  }

  .pantry-grid {
    width: 100%;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pantry-item-card {
    min-width: 0;
  }

  .receipt-match,
  .receipt-match__grid {
    min-width: 0;
    max-width: 100%;
  }

  .receipt-match__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  /* Meal planner is allowed to scroll only inside its card. */
  .meal-planner-card {
    width: 100%;
    max-width: 100%;
    overflow-x: auto;
  }

  .meal-board {
    min-width: 760px;
  }

  .planner-toolbar {
    width: 100%;
  }

  .dish-grid,
  .users-grid,
  .wallet-grid {
    width: 100%;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .deadline-row,
  .transaction-row,
  .todo-compose,
  .profile-editor,
  .settings-grid {
    min-width: 0;
    max-width: 100%;
  }

  .bottom-nav {
    width: 100%;
    max-width: 100vw;
    padding-left: max(5px, env(safe-area-inset-left));
    padding-right: max(5px, env(safe-area-inset-right));
  }
}

@media (max-width: 520px) {
  .content {
    padding-top: 10px;
    padding-right: max(8px, env(safe-area-inset-right));
    padding-left: max(8px, env(safe-area-inset-left));
  }

  .card {
    max-width: 100%;
    padding: 12px;
  }

  .calendar-card {
    padding: 0;
  }

  .page-intro {
    margin-bottom: 11px;
  }

  .page-intro h1 {
    font-size: 25px;
  }

  .page-intro p {
    display: none;
  }

  .quick-actions button {
    font-size: 9px;
    padding: 0 7px;
  }

  .quick-actions button svg:last-child {
    display: none;
  }

  .stat-card {
    min-height: 116px;
    padding: 11px;
  }

  .stat-card__icon {
    width: 34px;
    height: 34px;
    margin-bottom: 10px;
  }

  .stat-card strong {
    font-size: 19px;
  }

  .month-cell {
    min-height: 74px;
  }

  .month-cell__day {
    width: 24px;
    height: 24px;
  }

  .quick-input-row {
    grid-template-columns: minmax(0, 1fr) 54px 58px 40px;
  }

  .receipt-match__grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .modal-layer {
    width: 100%;
    max-width: 100vw;
  }

  .modal {
    max-width: 100vw;
  }
}

@media (max-width: 430px) {
  .topbar-profile {
    padding-right: 2px;
  }

  .stats-grid {
    gap: 7px;
  }

  .stat-card {
    min-height: 110px;
  }

  .pantry-grid,
  .dish-grid,
  .users-grid,
  .wallet-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .quick-input-row {
    grid-template-columns: minmax(0, 1fr) 50px 54px 38px;
  }

  .calendar-toolbar__nav {
    grid-template-columns: 34px auto 34px minmax(0, 1fr);
  }

  .calendar-toolbar__nav h2 {
    font-size: 12px;
  }

  .month-head > div {
    font-size: 7px;
  }

  .month-cell {
    min-height: 68px;
  }

  .month-cell__day {
    width: 22px;
    height: 22px;
    font-size: 9px;
  }

  .calendar-event strong,
  .calendar-more {
    font-size: 6.5px;
  }
}

@media (max-width: 360px) {
  .quick-actions {
    grid-template-columns: minmax(0, 1fr);
  }

  .stats-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .month-cell {
    min-height: 62px;
  }

  .calendar-event:nth-child(n+2) {
    display: none;
  }
}

/* Short landscape / embedded browser viewport */
@media (max-width: 900px) and (max-height: 560px) and (orientation: landscape) {
  :root {
    --topbar: 50px;
    --bottom: 56px;
  }

  .topbar {
    min-height: calc(var(--topbar) + env(safe-area-inset-top));
  }

  .content {
    padding-top: 8px;
    padding-bottom: calc(var(--bottom) + 8px + env(safe-area-inset-bottom));
  }

  .bottom-nav small {
    display: none;
  }

  .bottom-nav > button > span {
    height: 32px;
  }

  .page-intro p {
    display: none;
  }
}

@media (display-mode: standalone) and (max-width: 820px) {
  .topbar {
    padding-top: env(safe-area-inset-top);
  }

  .content {
    padding-bottom: calc(var(--bottom) + 16px + env(safe-area-inset-bottom));
  }
}


/* Tablet-first wall hub: shared layout rules for VerdoFamily */
.telegram-report-editor { display:grid; gap:14px; }
.telegram-report-basics { display:grid; grid-template-columns:minmax(0,1.4fr) minmax(150px,.6fr) minmax(210px,.8fr) minmax(210px,.8fr); gap:12px; align-items:end; }
.telegram-report-basics .segmented { width:100%; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); overflow:hidden; }
.telegram-report-basics .segmented button { width:100%; min-width:0; }
.telegram-report-body { display:grid; grid-template-columns:minmax(260px,.72fr) minmax(0,1.28fr); gap:12px; align-items:stretch; }
.telegram-report-panel { min-width:0; padding:14px; border:1px solid var(--border); border-radius:16px; background:var(--surface2); }
.telegram-report-panel__head { display:flex; align-items:flex-start; justify-content:space-between; gap:10px; margin-bottom:11px; }
.telegram-report-panel__head>div { display:flex; flex-direction:column; gap:3px; }
.telegram-report-panel__head strong { font-size:12px; }
.telegram-report-panel__head span { color:var(--muted); font-size:9px; }
.telegram-days-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:7px; }
.telegram-day-chip { min-height:48px; border:1px solid var(--border2); border-radius:13px; background:var(--surface); display:flex; align-items:center; justify-content:center; gap:7px; padding:8px 10px; cursor:pointer; user-select:none; transition:border-color .15s,background .15s,transform .15s; }
.telegram-day-chip:hover,.telegram-day-chip.is-selected { border-color:color-mix(in srgb,var(--accent) 60%,var(--border2)); background:color-mix(in srgb,var(--accent) 8%,var(--surface)); }
.telegram-day-chip:active { transform:scale(.98); }
.telegram-day-chip input { width:18px; height:18px; flex:0 0 auto; }
.telegram-day-chip span { font-size:10px; font-weight:850; }
.telegram-section-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; }
.telegram-section-option { min-width:0; min-height:58px; border:1px solid var(--border); border-radius:13px; background:var(--surface); display:grid; grid-template-columns:minmax(0,1fr) auto; align-items:center; gap:10px; padding:10px 11px; cursor:pointer; transition:border-color .15s,background .15s; }
.telegram-section-option.is-selected { border-color:color-mix(in srgb,var(--accent) 45%,var(--border)); background:color-mix(in srgb,var(--accent) 6%,var(--surface)); }
.telegram-section-option>div { min-width:0; display:flex; flex-direction:column; gap:2px; }
.telegram-section-option strong { font-size:11px; }
.telegram-section-option span { color:var(--muted); font-size:9px; line-height:1.25; }
.telegram-section-option input { width:19px; height:19px; }
.telegram-health-option { padding:12px 14px; }
.telegram-report-actions { margin-top:0; padding-top:2px; }

@media (min-width:821px) and (max-width:1280px) {
  :root { --sidebar:218px; --topbar:62px; }
  .sidebar { padding:14px 10px 12px; }
  .sidebar__nav>button { min-height:48px; padding:10px 11px; }
  .sidebar__nav>button strong { font-size:13px; }
  .content { padding:20px 20px 38px; }
  .page { max-width:none; }
  .card { padding:18px; }
  .card-header { margin-bottom:14px; }
  input,select,textarea { min-height:48px; }
  .btn { min-height:46px; }
  .telegram-report-basics { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .telegram-report-body { grid-template-columns:minmax(235px,.78fr) minmax(0,1.22fr); }
  .telegram-days-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
}

@media (max-width:980px) {
  .telegram-report-body { grid-template-columns:minmax(0,1fr); }
  .telegram-days-grid { grid-template-columns:repeat(7,minmax(0,1fr)); }
}

@media (max-width:820px) {
  .telegram-report-editor { gap:10px; }
  .telegram-report-basics { grid-template-columns:repeat(2,minmax(0,1fr)); gap:9px; }
  .telegram-report-panel { padding:12px; }
  .telegram-days-grid { grid-template-columns:repeat(4,minmax(0,1fr)); }
  .telegram-section-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .telegram-report-actions { position:sticky; bottom:calc(var(--bottom) + 7px + env(safe-area-inset-bottom)); z-index:4; padding:9px; margin:0 -4px; border:1px solid var(--border); border-radius:15px; background:color-mix(in srgb,var(--surface) 95%,transparent); backdrop-filter:blur(16px); box-shadow:var(--shadow); }
}

@media (max-width:560px) {
  .telegram-report-basics,.telegram-section-grid { grid-template-columns:minmax(0,1fr); }
  .telegram-days-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .telegram-report-actions { display:grid; grid-template-columns:minmax(0,1fr); }
  .telegram-report-actions .btn { width:100%; }
}


