  include_health: boolean
}

type TelegramStatus = {
  configured: boolean
  connected: boolean
  bot?: { username?: string; firstName?: string } | null
  botError?: string
  connection?: { telegramUsername?: string; firstName?: string; linkedAt?: string } | null
  schedules?: ReportSchedule[]
}

