]

function blankSchedule(): ReportSchedule {
  return {
    name: 'Buongiorno',
    enabled: true,
    time_local: '07:30',
    timezone: 'Europe/Rome',
    days: [1, 2, 3, 4, 5, 6, 7],
    target_day_offset: 0,
    scope: 'personal',
    sections: {
      agenda: true,
      meals: true,
      shopping: true,
      lowStock: false,
      deadlines: true,
      todos: true,
      chores: false,
      school: true
    },
    include_health: false
  }
}

function normalizeSchedule(value: any): ReportSchedule {
  const fallback = blankSchedule()
  return {
    ...fallback,
    ...value,
    time_local: String(value?.time_local || fallback.time_local).slice(0, 5),
    days: Array.isArray(value?.days) && value.days.length ? value.days.map(Number) : fallback.days,
    target_day_offset: Number(value?.target_day_offset || 0) === 1 ? 1 : 0,
    scope: value?.scope === 'family' ? 'family' : 'personal',
    sections: { ...fallback.sections, ...(value?.sections || {}) },
    include_health: value?.include_health === true
  }
}

export default function TelegramReportsCard() {
  const { familyId, cloudAuthenticated } = useFamily()
  const [status, setStatus] = useState<TelegramStatus | null>(null)
  const [draft, setDraft] = useState<ReportSchedule>(() => blankSchedule())
  const [busy, setBusy] = useState(false)
  const [message, setMessage] = useState('')
  const [linkCommand, setLinkCommand] = useState(() => sessionStorage.getItem('verdofamily_telegram_link_command') || '')
  const [linkUrl, setLinkUrl] = useState(() => sessionStorage.getItem('verdofamily_telegram_link_url') || '')

  useEffect(() => {
    void refreshStatus()
  }, [familyId, cloudAuthenticated])

  async function callTelegram(action: string, extra: Record<string, any> = {}) {
    if (!supabase || !familyId) throw new Error('Cloud non disponibile.')
    const { data, error } = await supabase.functions.invoke('telegram-reports', {
      body: { action, familyId, ...extra }
    })
    if (error) throw new Error(error.message || 'Errore Telegram')
    if (data?.error) throw new Error(data.error)
    return data
  }

  async function refreshStatus() {
    if (!supabase || !familyId || !cloudAuthenticated) {
      setStatus(null)
      return
    }
    setBusy(true)
    try {
      const result = await callTelegram('status')
      setStatus(result)
    } catch (error: any) {
      setMessage(`Telegram: ${error?.message || 'stato non disponibile'}`)
    } finally {
      setBusy(false)
    }
  }

  async function startLink() {
    setBusy(true)
    setMessage('')
    try {
      const result = await callTelegram('link-url')
      if (!result?.url) throw new Error('Link Telegram non disponibile.')
      const token = new URL(result.url).searchParams.get('start') || ''
      const command = result?.startCommand || (token ? `/start ${token}` : '')
      setLinkUrl(result.url)
      setLinkCommand(command)
      sessionStorage.setItem('verdofamily_telegram_link_url', result.url)
      sessionStorage.setItem('verdofamily_telegram_link_command', command)
      setMessage('Collegamento pronto. Premi “Apri bot” qui sotto; se Start non reagisce, copia e invia il comando manuale.')
    } catch (error: any) {
      setMessage(`Collegamento non riuscito: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBusy(false)
    }
  }

  async function copyLinkCommand() {
    if (!linkCommand) return
    try {
      await navigator.clipboard.writeText(linkCommand)
      setMessage('Comando copiato. Apri la chat privata del bot Telegram, incollalo e invialo.')
    } catch {
      setMessage('Copia manualmente il comando qui sotto e invialo nella chat privata del bot Telegram.')
    }
  }

  async function pollLink() {
    setBusy(true)
    setMessage('')
    try {
      const result = await callTelegram('poll-link')
      setStatus(result)
      if (result?.connected) {
        sessionStorage.removeItem('verdofamily_telegram_link_url')
        sessionStorage.removeItem('verdofamily_telegram_link_command')
        setLinkUrl('')
        setLinkCommand('')
        setMessage('✅ Telegram collegato correttamente.')
      } else {
        setMessage('Non vedo ancora il collegamento. Apri il bot, premi Avvia e riprova tra qualche secondo.')
      }
    } catch (error: any) {
      setMessage(`Verifica non riuscita: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBusy(false)
    }
  }

  async function disconnect() {
    if (!confirm('Scollegare Telegram da VerdoFamily? I report resteranno configurati ma non verranno inviati finché non ricolleghi un account.')) return
    setBusy(true)
    try {
      await callTelegram('disconnect')
      setMessage('Telegram scollegato.')
      await refreshStatus()
    } catch (error: any) {
      setMessage(`Scollegamento non riuscito: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBusy(false)
    }
  }

  function toggleDay(day: number) {
    const current = draft.days.includes(day)
    const next = current ? draft.days.filter(item => item !== day) : [...draft.days, day].sort()
    if (!next.length) return
    setDraft({ ...draft, days: next })
  }

  function toggleSection(key: SectionKey) {
    setDraft({ ...draft, sections: { ...draft.sections, [key]: !draft.sections[key] } })
  }

  function editSchedule(schedule: ReportSchedule) {
    setDraft(normalizeSchedule(schedule))
    setMessage('Modifica il report e poi premi “Salva report”.')
  }

  function newSchedule() {
    setDraft(blankSchedule())
    setMessage('Nuovo report: scegli orario, giorni e contenuti.')
  }

  async function saveSchedule() {
    setBusy(true)
    setMessage('')
    try {
      const result = await callTelegram('save-schedule', { schedule: draft })
      setStatus(result)
      setDraft(blankSchedule())
      setMessage('✅ Report salvato. Verrà inviato automaticamente all’orario scelto.')
    } catch (error: any) {
      setMessage(`Salvataggio non riuscito: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBusy(false)
    }
  }

  async function deleteSchedule(id?: string) {
    if (!id || !confirm('Eliminare questo report automatico?')) return
    setBusy(true)
    try {
      const result = await callTelegram('delete-schedule', { scheduleId: id })
      setStatus(result)
      if (draft.id === id) setDraft(blankSchedule())
      setMessage('Report eliminato.')
    } catch (error: any) {
      setMessage(`Eliminazione non riuscita: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBusy(false)
    }
  }

  async function sendTest(id?: string) {
    if (!id) return
    setBusy(true)
    setMessage('')
    try {
      await callTelegram('send-test', { scheduleId: id })
      setMessage('✅ Report di prova inviato su Telegram.')
    } catch (error: any) {
      setMessage(`Invio di prova non riuscito: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBusy(false)
    }
  }

  return <Card className="settings-card--wide">
    <CardHeader
      title="Telegram & report automatici"
      subtitle="Ricevi gratuitamente agenda, pasti, spesa e altri riepiloghi anche quando VerdoFamily è chiuso."
      action={status?.connected ? <Button variant="soft" size="sm" icon={<Plus size={15} />} onClick={newSchedule}>Nuovo report</Button> : null}
    />

    {!cloudAuthenticated || !familyId ? <div className="callout">Accedi con il tuo account VerdoFamily cloud per configurare i report automatici.</div> : !status ? <div className="backup-actions"><Button variant="soft" icon={<RefreshCw size={17} />} onClick={refreshStatus} disabled={busy}>{busy ? 'Controllo…' : 'Verifica Telegram'}</Button></div> : !status.configured ? <div className="callout">Il backend è pronto, ma manca il secret <strong>TELEGRAM_BOT_TOKEN</strong> su Supabase.</div> : !status.connected ? <>
      <div className="callout"><Bot size={17} /> Collega il tuo account Telegram personale. Ogni membro della famiglia potrà collegare il proprio account separatamente.</div>
      <div className="backup-actions">
        <Button icon={<ExternalLink size={17} />} onClick={startLink} disabled={busy}>{busy ? 'Preparazione…' : `Collega @${status.bot?.username || 'bot Telegram'}`}</Button>
        <Button variant="soft" icon={<RefreshCw size={17} />} onClick={pollLink} disabled={busy}>Verifica collegamento</Button>
      </div>
      {linkCommand ? <div className="callout" style={{ marginTop: 12 }}>
        <strong>Se “Start bot” non reagisce</strong><br />
        Cerca <strong>@{status.bot?.username || 'il bot Telegram'}</strong> direttamente nell'app Telegram, apri la chat privata e invia questo comando:
        <div className="backup-actions" style={{ marginTop: 10 }}>
          <input readOnly value={linkCommand} style={{ flex: 1, minWidth: 220 }} onFocus={e => e.currentTarget.select()} />
          <Button variant="soft" onClick={copyLinkCommand}>Copia comando</Button>
          {linkUrl ? <Button variant="ghost" onClick={() => window.location.assign(linkUrl)}>Apri bot</Button> : null}
        </div>
        <small>Il comando è temporaneo e collega soltanto il tuo utente VerdoFamily.</small>
      </div> : null}
    </> : <>
      <div className="callout callout--success"><CheckCircle2 size={17} /> <strong>Telegram collegato</strong>{status.connection?.firstName ? ` · ${status.connection.firstName}` : ''}{status.connection?.telegramUsername ? ` (@${status.connection.telegramUsername})` : ''}</div>

      {(status.schedules || []).length ? <>
        <CardHeader title="Report attivi" subtitle="Puoi creare più invii nella stessa giornata." />
        <div className="sortable-list">{(status.schedules || []).map(schedule => <div key={schedule.id}>
          <span><strong>{schedule.name}</strong> · {schedule.time_local} · {schedule.target_day_offset === 1 ? 'giorno successivo' : 'giorno stesso'} · {schedule.scope === 'family' ? 'famiglia' : 'personale'}{schedule.enabled ? '' : ' · disattivato'}</span>
          <div>
            <button onClick={() => editSchedule(schedule)} disabled={busy}>Modifica</button>
            <button onClick={() => sendTest(schedule.id)} disabled={busy}>Prova</button>
            <button onClick={() => deleteSchedule(schedule.id)} disabled={busy}>Elimina</button>
          </div>
        </div>)}</div>
      </> : <div className="callout">Nessun report programmato. Configura il primo qui sotto.</div>}

      <CardHeader title={draft.id ? `Modifica “${draft.name}”` : 'Configura un report'} subtitle="Impostazioni compatte e touch-friendly, pensate anche per il tablet di casa." />
      <div className="telegram-report-editor">
        <div className="telegram-report-basics">
          <Field label="Nome report"><input value={draft.name} onChange={e => setDraft({ ...draft, name: e.target.value })} placeholder="Es. Buongiorno" /></Field>
          <Field label="Orario"><input type="time" value={draft.time_local} onChange={e => setDraft({ ...draft, time_local: e.target.value })} /></Field>
          <Field label="Giorno del riepilogo"><Segmented value={String(draft.target_day_offset)} onChange={(value: string) => setDraft({ ...draft, target_day_offset: value === '1' ? 1 : 0 })} options={[{ value: '0', label: 'Oggi' }, { value: '1', label: 'Domani' }]} /></Field>
          <Field label="Contenuti"><Segmented value={draft.scope} onChange={(scope: 'personal' | 'family') => setDraft({ ...draft, scope })} options={[{ value: 'personal', label: 'I miei' }, { value: 'family', label: 'Famiglia' }]} /></Field>
        </div>

        <div className="telegram-report-body">
          <section className="telegram-report-panel">
            <div className="telegram-report-panel__head"><div><strong>Giorni di invio</strong><span>Quando deve arrivare questo report</span></div></div>
            <div className="telegram-days-grid">{DAY_OPTIONS.map(day => <label key={day.value} className={`telegram-day-chip ${draft.days.includes(day.value) ? 'is-selected' : ''}`}><input type="checkbox" checked={draft.days.includes(day.value)} onChange={() => toggleDay(day.value)} /><span>{day.label}</span></label>)}</div>
          </section>

          <section className="telegram-report-panel telegram-report-panel--sections">
            <div className="telegram-report-panel__head"><div><strong>Sezioni del report</strong><span>Scegli cosa vuoi ricevere nel messaggio</span></div></div>
            <div className="telegram-section-grid">{SECTION_OPTIONS.map(section => <label key={section.key} className={`telegram-section-option ${draft.sections[section.key] ? 'is-selected' : ''}`}><div><strong>{section.label}</strong><span>{section.hint}</span></div><input type="checkbox" checked={draft.sections[section.key]} onChange={() => toggleSection(section.key)} /></label>)}</div>
          </section>
        </div>

        <div className="callout telegram-health-option">
          <label className="toggle-row"><input type="checkbox" checked={draft.include_health} onChange={e => setDraft({ ...draft, include_health: e.target.checked })} /><span><strong>Includi dati salute</strong><br />Disattivato di default: visite, terapie e promemoria sanitari non escono dall’app finché non lo abiliti espressamente.</span></label>
        </div>

        <div className="backup-actions telegram-report-actions">
          <Button icon={<Send size={17} />} onClick={saveSchedule} disabled={busy}>{busy ? 'Salvataggio…' : 'Salva report'}</Button>
          {draft.id ? <Button variant="soft" onClick={newSchedule} disabled={busy}>Annulla modifica</Button> : null}
          <Button variant="ghost" icon={<Unlink size={17} />} onClick={disconnect} disabled={busy}>Scollega Telegram</Button>
        </div>
      </div>
    </>}

    {message ? <div className="callout" style={{ marginTop: 12 }}>{message}</div> : null}
  </Card>
}

import React, { useEffect, useMemo, useState } from 'react'
import {
  Bell,
  Camera,
  Image as ImageIcon,
  Megaphone,
  MessageCircle,
  Pencil,
  Pin,
  PinOff,
  Plus,
  StickyNote,
  Trash2,
  Upload
} from 'lucide-react'
import { useFamily } from '../store'
import { supabase } from '../supabaseClient'
import type { BoardAttachment, BoardPost, BoardPostType } from '../types'
import { Avatar, Badge, Button, Card, CardHeader, EmptyState, Field, IconButton, Modal, PageIntro, Segmented } from '../ui'
import { localDateISO } from '../utils'

const TYPE_OPTIONS: Array<{ value: BoardPostType; label: string }> = [
  { value: 'message', label: 'Messaggio' },
  { value: 'note', label: 'Nota' },
  { value: 'reminder', label: 'Promemoria' },
  { value: 'photo', label: 'Foto' }
]

function typeLabel(type: BoardPostType) {
  return TYPE_OPTIONS.find(item => item.value === type)?.label || 'Nota'
}

function typeIcon(type: BoardPostType) {
  if (type === 'message') return <MessageCircle size={16} />
  if (type === 'reminder') return <Bell size={16} />
  if (type === 'photo') return <Camera size={16} />
  return <StickyNote size={16} />
}

function formatWhen(value: string) {
  try {
    return new Intl.DateTimeFormat('it-IT', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value))
  } catch {
    return value
  }
}

function BoardPhoto({ attachment, familyId }: { attachment: BoardAttachment; familyId: string | null }) {
  const [url, setUrl] = useState('')
  const [failed, setFailed] = useState(false)

  useEffect(() => {
    let active = true
    setUrl('')
    setFailed(false)
    if (!supabase || !familyId || !attachment.path) {
      setFailed(true)
      return
    }
    supabase.functions.invoke('noticeboard-attachment', {
      body: { action: 'signed-url', familyId, path: attachment.path }
    }).then(({ data, error }) => {
      if (!active) return
      if (error || !data?.ok || !data?.signedUrl) {
        setFailed(true)
        return
      }
      setUrl(data.signedUrl)
    }).catch(() => {
      if (active) setFailed(true)
    })
    return () => { active = false }
  }, [attachment.path, familyId])

  if (failed) return <div className="board-photo board-photo--missing"><ImageIcon size={24} /><span>Foto non disponibile</span></div>
  if (!url) return <div className="board-photo board-photo--loading"><ImageIcon size={24} /></div>
  return <img className="board-photo" src={url} alt={attachment.name || 'Foto bacheca'} />
}

export default function BoardPage() {
  const {
    data,
    authUser,
    familyId,
    cloudAuthenticated,
    upsertBoardPost,
    toggleBoardPin,
    deleteBoardPost,
    addBoardAttachment,
    removeBoardAttachment
  } = useFamily()

  const [view, setView] = useState<'wall' | 'recent' | 'mine'>('wall')
  const [editing, setEditing] = useState<any>(null)
  const [quickMessage, setQuickMessage] = useState('')
  const [pendingFile, setPendingFile] = useState<File | null>(null)
  const [busy, setBusy] = useState(false)
  const [photoMessage, setPhotoMessage] = useState('')

  const today = localDateISO()
  const isChild = authUser?.role === 'bimbo'

  function canSee(post: BoardPost) {
    if (!authUser) return false
    if (post.authorUserId === authUser.id) return true
    if (post.audience === 'family') return true
    return (post.userIds || []).includes(authUser.id)
  }

  function canEdit(post: BoardPost) {
    if (!authUser) return false
    return authUser.role !== 'bimbo' || post.authorUserId === authUser.id
  }

  const visible = useMemo(
    () => data.boardPosts.filter(canSee).slice().sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)),
    [data.boardPosts, authUser?.id, authUser?.role]
  )

  const pinned = visible.filter(post => post.pinned)
  const activeReminders = visible.filter(post => post.type === 'reminder' && post.dueDate && post.dueDate >= today)
  const photos = visible.filter(post => post.attachments?.length)
  const mine = visible.filter(post => post.authorUserId === authUser?.id)

  const shown = view === 'mine'
    ? mine
    : view === 'recent'
      ? visible
      : visible.filter(post => post.pinned || post.type === 'reminder' || post.updatedAt.slice(0, 10) >= localDateISO(new Date(Date.now() - 7 * 86400000)))

  function openNew(type: BoardPostType = 'note') {
    setPhotoMessage('')
    setPendingFile(null)
    setEditing({
      id: undefined,
      type,
      title: '',
      body: '',
      audience: 'family',
      userIds: [],
      pinned: false,
      dueDate: '',
      attachments: []
    })
  }

  function openEdit(post: BoardPost) {
    if (!canEdit(post)) return
    setPhotoMessage('')
    setPendingFile(null)
    setEditing({ ...post, userIds: [...(post.userIds || [])], attachments: [...(post.attachments || [])] })
  }

  function toggleTarget(userId: number) {
    if (!editing) return
    const ids: number[] = editing.userIds || []
    setEditing({ ...editing, userIds: ids.includes(userId) ? ids.filter(id => id !== userId) : [...ids, userId] })
  }

  async function uploadPhoto(postId: string, file: File) {
    if (!supabase || !familyId || !cloudAuthenticated) throw new Error('Le foto richiedono l’accesso cloud.')
    const form = new FormData()
    form.append('action', 'upload')
    form.append('familyId', familyId)
    form.append('postId', postId)
    form.append('file', file)
    const { data: result, error } = await supabase.functions.invoke('noticeboard-attachment', { body: form })
    if (error || !result?.ok || !result?.attachment) throw new Error(error?.message || result?.error || 'Caricamento non riuscito')
    addBoardAttachment(postId, result.attachment)
    return result.attachment as BoardAttachment
  }

  async function savePost() {
    if (!editing || (!editing.title?.trim() && !editing.body?.trim() && !pendingFile && !(editing.attachments || []).length)) return
    if (editing.audience === 'users' && !(editing.userIds || []).length) {
      setPhotoMessage('Scegli almeno un destinatario oppure imposta “Tutta la famiglia”.')
      return
    }
    setBusy(true)
    setPhotoMessage('')
    const id = upsertBoardPost({
      id: editing.id,
      type: editing.type,
      title: editing.title || '',
      body: editing.body || '',
      audience: editing.audience,
      userIds: editing.userIds || [],
      pinned: !!editing.pinned,
      dueDate: editing.type === 'reminder' ? (editing.dueDate || undefined) : undefined,
      attachments: editing.attachments || []
    })

    try {
      if (pendingFile) await uploadPhoto(id, pendingFile)
      setEditing(null)
      setPendingFile(null)
    } catch (error: any) {
      setEditing({ ...editing, id })
      setPhotoMessage(`Post salvato, ma la foto non è stata caricata: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBusy(false)
    }
  }

  async function deleteAttachment(attachment: BoardAttachment) {
    if (!editing?.id || !familyId || !supabase) return
    setBusy(true)
    setPhotoMessage('')
    try {
      const { data: result, error } = await supabase.functions.invoke('noticeboard-attachment', {
        body: { action: 'delete', familyId, path: attachment.path }
      })
      if (error || !result?.ok) throw new Error(error?.message || result?.error || 'Eliminazione non riuscita')
      removeBoardAttachment(editing.id, attachment.id)
      setEditing({
        ...editing,
        attachments: (editing.attachments || []).filter((item: BoardAttachment) => item.id !== attachment.id)
      })
    } catch (error: any) {
      setPhotoMessage(error?.message || 'Impossibile eliminare la foto.')
    } finally {
      setBusy(false)
    }
  }

  async function deletePost(post: BoardPost) {
    if (!canEdit(post) || !confirm('Eliminare questo contenuto dalla bacheca?')) return
    setBusy(true)
    try {
      if (supabase && familyId && post.attachments?.length) {
        await Promise.allSettled(post.attachments.map(attachment =>
          supabase.functions.invoke('noticeboard-attachment', { body: { action: 'delete', familyId, path: attachment.path } })
        ))
      }
      deleteBoardPost(post.id)
      if (editing?.id === post.id) setEditing(null)
    } finally {
      setBusy(false)
    }
  }

  function sendQuickMessage() {
    const body = quickMessage.trim()
    if (!body) return
    upsertBoardPost({
      type: 'message',
      title: '',
      body,
      audience: 'family',
      userIds: [],
      pinned: false
    })
    setQuickMessage('')
  }

  function audienceText(post: BoardPost) {
    if (post.audience === 'family') return 'Tutta la famiglia'
    const names = (post.userIds || []).map(id => data.users.find(user => user.id === id)?.name).filter(Boolean)
    return names.join(', ') || 'Destinatari'
  }

  function reminderTone(post: BoardPost) {
    if (!post.dueDate) return 'neutral' as const
    if (post.dueDate < today) return 'danger' as const
    if (post.dueDate === today) return 'warning' as const
    return 'neutral' as const
  }

  return <div className="page page--board">
    <PageIntro
      eyebrow="Famiglia"
      title="Bacheca"
      description="Il frigorifero digitale di casa: messaggi, note, foto e promemoria importanti sempre visibili."
      actions={<Button icon={<Plus size={18} />} onClick={() => openNew('note')}>Nuovo contenuto</Button>}
    />

    <Card className="board-quick-compose">
      <div className="board-quick-compose__icon"><Megaphone size={20} /></div>
      <input
        value={quickMessage}
        onChange={e => setQuickMessage(e.target.value)}
        onKeyDown={e => { if (e.key === 'Enter') sendQuickMessage() }}
        placeholder="Scrivi un messaggio veloce alla famiglia…"
      />
      <Button size="sm" onClick={sendQuickMessage} disabled={!quickMessage.trim()}>Pubblica</Button>
      <Button size="sm" variant="soft" icon={<Camera size={16} />} onClick={() => openNew('photo')}>Foto</Button>
    </Card>

    <div className="board-stats">
      <Card className="board-stat"><Pin size={17} /><span><strong>{pinned.length}</strong><small>fissati in alto</small></span></Card>
      <Card className="board-stat"><Bell size={17} /><span><strong>{activeReminders.length}</strong><small>promemoria attivi</small></span></Card>
      <Card className="board-stat"><Camera size={17} /><span><strong>{photos.length}</strong><small>post con foto</small></span></Card>
    </div>

    <div className="page-tabs-wrap">
      <Segmented
        value={view}
        onChange={setView}
        options={[
          { value: 'wall', label: 'In evidenza' },
          { value: 'recent', label: `Tutta la bacheca · ${visible.length}` },
          { value: 'mine', label: `I miei · ${mine.length}` }
        ]}
      />
    </div>

    {view === 'wall' && pinned.length ? <section className="board-pinned-section">
      <div className="board-section-title"><Pin size={16} /><div><strong>Fissati sul tablet</strong><small>Restano sempre in primo piano.</small></div></div>
      <div className="board-pinned-grid">
        {pinned.map(post => <BoardCard key={post.id} post={post} familyId={familyId} data={data} authUser={authUser} canEdit={canEdit(post)} audienceText={audienceText(post)} reminderTone={reminderTone(post)} onEdit={() => openEdit(post)} onPin={() => toggleBoardPin(post.id)} onDelete={() => deletePost(post)} />)}
      </div>
    </section> : null}

    <section className="board-feed-section">
      <div className="board-section-title"><StickyNote size={16} /><div><strong>{view === 'wall' ? 'Da non perdere' : view === 'mine' ? 'I miei contenuti' : 'Tutta la bacheca'}</strong><small>Messaggi, note, foto e promemoria in ordine di aggiornamento.</small></div></div>
      {shown.length ? <div className="board-feed-grid">
        {shown.filter(post => view !== 'wall' || !post.pinned).map(post => <BoardCard key={post.id} post={post} familyId={familyId} data={data} authUser={authUser} canEdit={canEdit(post)} audienceText={audienceText(post)} reminderTone={reminderTone(post)} onEdit={() => openEdit(post)} onPin={() => toggleBoardPin(post.id)} onDelete={() => deletePost(post)} />)}
      </div> : <Card><EmptyState icon={<StickyNote size={30} />} title="Bacheca vuota" text="Pubblica un messaggio, una foto o un promemoria per la famiglia." action={<Button onClick={() => openNew('message')}>Scrivi il primo messaggio</Button>} /></Card>}
    </section>

    <Modal
      open={!!editing}
      onClose={() => !busy && setEditing(null)}
      title={editing?.id ? 'Modifica bacheca' : 'Nuovo contenuto'}
      footer={<div className="modal-actions">
        <div>{editing?.id ? <Button variant="danger" disabled={busy} icon={<Trash2 size={16} />} onClick={() => { const post = data.boardPosts.find(item => item.id === editing.id); if (post) void deletePost(post) }}>Elimina</Button> : null}</div>
        <div className="modal-actions__right"><Button variant="ghost" disabled={busy} onClick={() => setEditing(null)}>Annulla</Button><Button disabled={busy} onClick={savePost}>{busy ? 'Salvataggio…' : 'Salva'}</Button></div>
      </div>}
    >
      {editing ? <div className="form-grid form-grid--2">
        <Field label="Tipo">
          <select value={editing.type} onChange={e => setEditing({ ...editing, type: e.target.value as BoardPostType })}>
            {TYPE_OPTIONS.map(item => <option key={item.value} value={item.value}>{item.label}</option>)}
          </select>
        </Field>
        <Field label="Visibilità">
          <select value={editing.audience} onChange={e => setEditing({ ...editing, audience: e.target.value, userIds: e.target.value === 'family' ? [] : editing.userIds })}>
            <option value="family">Tutta la famiglia</option>
            <option value="users">Solo alcune persone</option>
          </select>
        </Field>

        <Field label="Titolo" className="field--wide" hint="Facoltativo per i messaggi veloci">
          <input value={editing.title || ''} onChange={e => setEditing({ ...editing, title: e.target.value })} placeholder="Es. Ricordarsi le chiavi" />
        </Field>

        <Field label="Messaggio" className="field--wide">
          <textarea rows={4} value={editing.body || ''} onChange={e => setEditing({ ...editing, body: e.target.value })} placeholder="Scrivi qui il contenuto…" />
        </Field>

        {editing.audience === 'users' ? <Field label="Destinatari" className="field--wide">
          <div className="board-user-picker">
            {data.users.map(user => {
              const selected = (editing.userIds || []).includes(user.id)
              return <button type="button" key={user.id} className={selected ? 'is-active' : ''} onClick={() => toggleTarget(user.id)}><Avatar user={user} size="xs" /> {user.name}</button>
            })}
          </div>
        </Field> : null}

        {editing.type === 'reminder' ? <Field label="Data promemoria">
          <input type="date" value={editing.dueDate || ''} onChange={e => setEditing({ ...editing, dueDate: e.target.value })} />
        </Field> : null}

        {!isChild ? <label className="toggle-row field--wide"><input type="checkbox" checked={!!editing.pinned} onChange={e => setEditing({ ...editing, pinned: e.target.checked })} /><span><strong>Fissa in alto</strong><small>Resta sempre ben visibile nella bacheca e nella Home del tablet.</small></span></label> : null}

        <Field label="Foto" className="field--wide" hint="JPG, PNG, WEBP o HEIC · massimo 12 MB">
          <label className="board-upload-button">
            <Upload size={16} />
            <span>{pendingFile ? pendingFile.name : 'Scegli una foto'}</span>
            <input hidden type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,image/*" onChange={e => setPendingFile(e.target.files?.[0] || null)} />
          </label>
        </Field>

        {(editing.attachments || []).length ? <div className="board-modal-attachments field--wide">
          {(editing.attachments || []).map((attachment: BoardAttachment) => <div key={attachment.id}>
            <BoardPhoto attachment={attachment} familyId={familyId} />
            <button type="button" disabled={busy} onClick={() => void deleteAttachment(attachment)}><Trash2 size={14} /> Rimuovi</button>
          </div>)}
        </div> : null}

        {photoMessage ? <div className="callout field--wide">{photoMessage}</div> : null}
      </div> : null}
    </Modal>
  </div>
}

function BoardCard({
  post,
  familyId,
  data,
  authUser,
  canEdit,
  audienceText,
  reminderTone,
  onEdit,
  onPin,
  onDelete
}: {
  post: BoardPost
  familyId: string | null
  data: any
  authUser: any
  canEdit: boolean
  audienceText: string
  reminderTone: 'neutral' | 'warning' | 'danger'
  onEdit: () => void
  onPin: () => void
  onDelete: () => void
}) {
  const author = data.users.find((user: any) => user.id === post.authorUserId)
  return <Card className={`board-card board-card--${post.type} ${post.pinned ? 'is-pinned' : ''}`}>
    <div className="board-card__top">
      <div className="board-card__type">{typeIcon(post.type)}<span>{typeLabel(post.type)}</span></div>
      <div className="board-card__actions">
        {post.pinned ? <Badge tone="warning"><Pin size={11} /> Fissato</Badge> : null}
        {canEdit && authUser?.role !== 'bimbo' ? <IconButton label={post.pinned ? 'Togli dai fissati' : 'Fissa in alto'} onClick={onPin}>{post.pinned ? <PinOff size={15} /> : <Pin size={15} />}</IconButton> : null}
        {canEdit ? <IconButton label="Modifica" onClick={onEdit}><Pencil size={15} /></IconButton> : null}
        {canEdit ? <IconButton label="Elimina" onClick={onDelete}><Trash2 size={15} /></IconButton> : null}
      </div>
    </div>

    {post.attachments?.length ? <div className={`board-card__photos ${post.attachments.length > 1 ? 'has-many' : ''}`}>
      {post.attachments.slice(0, 4).map(attachment => <BoardPhoto key={attachment.id} attachment={attachment} familyId={familyId} />)}
    </div> : null}

    <div className="board-card__copy">
      {post.title ? <strong>{post.title}</strong> : null}
      {post.body ? <p>{post.body}</p> : null}
    </div>

    {post.type === 'reminder' && post.dueDate ? <div className="board-card__due"><Badge tone={reminderTone}><Bell size={12} /> {post.dueDate.split('-').reverse().join('/')}</Badge></div> : null}

    <div className="board-card__footer">
      <div>{author ? <Avatar user={author} size="xs" /> : null}<span><strong>{author?.name || 'Famiglia'}</strong><small>{audienceText}</small></span></div>
      <time>{formatWhen(post.updatedAt)}</time>
    </div>
  </Card>
}

import React, { useMemo, useState } from 'react'
import { CalendarPlus, ChevronLeft, ChevronRight, Clock3, Pencil, Trash2 } from 'lucide-react'
import type { CalendarEvent } from '../types'
import { useFamily } from '../store'
import { Avatar, Button, Card, EmptyState, Field, IconButton, Modal, PageIntro, Segmented } from '../ui'
import { addDays, dayLabel, localDateISO, monthCells, monthTitle, parseISODate, weekDates } from '../utils'

const emptyEvent = (date: string, userId: number) => ({ id: undefined, title: '', date, time: '', endTime: '', userId, userIds: [userId], audience: 'users', notes: '' })

export default function CalendarPage() {
  const { data, authUser, upsertCalendarEvent, deleteCalendarEvent } = useFamily()
  const today = localDateISO()
  const [view, setView] = useState<'month' | 'week' | 'agenda'>('month')
  const [cursor, setCursor] = useState(today)
  const [editing, setEditing] = useState<any>(null)

  const cells = useMemo(() => monthCells(cursor), [cursor])
  const week = useMemo(() => weekDates(cursor), [cursor])
  const eventsByDate = useMemo(() => {
    const map: Record<string, CalendarEvent[]> = {}
    for (const event of data.calendarEvents) {
      map[event.date] ||= []
      map[event.date].push(event)
    }
    Object.values(map).forEach(list => list.sort((a, b) => (a.time || '').localeCompare(b.time || '')))
    return map
  }, [data.calendarEvents])

  const agenda = useMemo(
    () => data.calendarEvents.slice().sort((a, b) => `${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)),
    [data.calendarEvents]
  )

  function participantIds(event: any) {
    if (event?.audience === 'family') return data.users.map(user => user.id)
    const ids = Array.isArray(event?.userIds) && event.userIds.length ? event.userIds.map(Number) : [Number(event?.userId || 0)]
    return Array.from(new Set(ids.filter((id: number) => id > 0))) as number[]
  }

  function peopleLabel(event: any) {
    if (event?.audience === 'family') return 'Famiglia'
    const names = participantIds(event).map(id => data.users.find(user => user.id === id)?.name).filter(Boolean)
    return names.join(', ') || 'Nessuno'
  }

  function primaryUser(event: any) {
    return data.users.find(user => user.id === participantIds(event)[0])
  }

  function move(direction: -1 | 1) {
    if (view === 'month') {
      const d = parseISODate(cursor)
      d.setMonth(d.getMonth() + direction)
      setCursor(localDateISO(d))
    } else {
      setCursor(addDays(cursor, 7 * direction))
    }
  }

  function openNew(date = cursor) {
    setEditing(emptyEvent(date, authUser?.id || data.users[0]?.id || 1))
  }

  function openEdit(event: CalendarEvent) {
    setEditing({ ...event, audience: event.audience || 'users', userIds: participantIds(event) })
  }

  function toggleParticipant(id: number) {
    if (!editing) return
    const current = participantIds(editing)
    const next = current.includes(id) ? current.filter(item => item !== id) : [...current, id]
    setEditing({ ...editing, audience: 'users', userIds: next, userId: next[0] || editing.userId })
  }

  function save() {
    if (!editing?.title?.trim() || !editing?.date) return
    const audience = editing.audience === 'family' ? 'family' : 'users'
    const userIds = audience === 'family' ? data.users.map(user => user.id) : participantIds(editing)
    if (!userIds.length) return alert('Seleziona almeno una persona oppure scegli Tutta la famiglia.')
    upsertCalendarEvent({
      ...editing,
      title: editing.title.trim(),
      userId: Number(userIds[0]),
      userIds,
      audience,
      time: editing.time || '',
      endTime: editing.endTime || ''
    })
    setEditing(null)
  }

  return (
    <div className="page">
      <PageIntro eyebrow="Organizzazione" title="Calendario" description="Impegni personali, condivisi tra più persone o per tutta la famiglia." actions={<Button icon={<CalendarPlus size={18} />} onClick={() => openNew(today)}>Nuovo impegno</Button>} />

      <Card className="calendar-card">
        <div className="calendar-toolbar">
          <div className="calendar-toolbar__nav">
            <IconButton label="Indietro" onClick={() => move(-1)}><ChevronLeft size={20} /></IconButton>
            <button className="today-btn" onClick={() => setCursor(today)}>Oggi</button>
            <IconButton label="Avanti" onClick={() => move(1)}><ChevronRight size={20} /></IconButton>
            <h2>{view === 'month' ? monthTitle(cursor) : `${dayLabel(week[0], true)} – ${dayLabel(week[6], true)}`}</h2>
          </div>
          <Segmented value={view} onChange={setView} options={[{ value: 'month', label: 'Mese' }, { value: 'week', label: 'Settimana' }, { value: 'agenda', label: 'Agenda' }]} />
        </div>

        {view === 'month' ? (
          <div className="month-view">
            <div className="month-head">{['Lun', 'Mar', 'Mer', 'Gio', 'Ven', 'Sab', 'Dom'].map(day => <div key={day}>{day}</div>)}</div>
            <div className="month-grid">
              {cells.map(cell => {
                const list = eventsByDate[cell.date] || []
                return (
                  <div key={cell.date} className={`month-cell ${!cell.inMonth ? 'is-muted' : ''} ${cell.date === today ? 'is-today' : ''}`}>
                    <button className="month-cell__day" onClick={() => openNew(cell.date)}>{Number(cell.date.slice(8, 10))}</button>
                    <div className="month-cell__events">
                      {list.slice(0, 3).map(event => {
                        const user = primaryUser(event)
                        return <button key={event.id} className="calendar-event" onClick={() => openEdit(event)} style={{ '--event-color': user?.color || '#5B5BD6' } as React.CSSProperties}><span>{event.time || '•'}</span><strong>{event.title}</strong></button>
                      })}
                      {list.length > 3 ? <span className="calendar-more">+{list.length - 3} altri</span> : null}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        ) : null}

        {view === 'week' ? (
          <div className="week-calendar">
            {week.map(date => (
              <section key={date} className={`week-calendar__day ${date === today ? 'is-today' : ''}`}>
                <button className="week-calendar__head" onClick={() => openNew(date)}><span>{dayLabel(date)}</span><strong>{Number(date.slice(8, 10))}</strong></button>
                <div className="week-calendar__events">
                  {(eventsByDate[date] || []).map(event => {
                    const user = primaryUser(event)
                    return <button key={event.id} className="week-event" onClick={() => openEdit(event)} style={{ '--event-color': user?.color || '#5B5BD6' } as React.CSSProperties}><span className="week-event__time"><Clock3 size={13} /> {event.time || 'Tutto il giorno'}</span><strong>{event.title}</strong><span>{peopleLabel(event)}</span></button>
                  })}
                  {!(eventsByDate[date] || []).length ? <button className="week-empty" onClick={() => openNew(date)}>+ Aggiungi</button> : null}
                </div>
              </section>
            ))}
          </div>
        ) : null}

        {view === 'agenda' ? (
          <div className="agenda-list">
            {agenda.length ? agenda.map(event => {
              const user = primaryUser(event)
              return <button key={event.id} className="agenda-row" onClick={() => openEdit(event)}><div className="agenda-date"><strong>{event.date.slice(8, 10)}</strong><span>{parseISODate(event.date).toLocaleDateString('it-IT', { month: 'short' })}</span></div><div className="agenda-time">{event.time || '—'}</div><div className="agenda-copy"><strong>{event.title}</strong><span>{event.notes || 'Nessuna nota'}</span></div><div className="agenda-user">{event.audience === 'family' ? <span>Famiglia</span> : <><Avatar user={user} size="sm" /><span>{peopleLabel(event)}</span></>}</div><ChevronRight size={18} /></button>
            }) : <EmptyState icon={<CalendarPlus size={30} />} title="Calendario vuoto" text="Aggiungi il primo impegno della famiglia." action={<Button onClick={() => openNew(today)}>Aggiungi impegno</Button>} />}
          </div>
        ) : null}
      </Card>

      <Modal open={!!editing} onClose={() => setEditing(null)} title={editing?.id ? 'Modifica impegno' : 'Nuovo impegno'} subtitle="Puoi assegnarlo a una persona, più persone oppure a tutta la famiglia." footer={<div className="modal-actions">{editing?.id ? <Button variant="danger" icon={<Trash2 size={17} />} onClick={() => { deleteCalendarEvent(editing.id); setEditing(null) }}>Elimina</Button> : <span />}<div className="modal-actions__right"><Button variant="ghost" onClick={() => setEditing(null)}>Annulla</Button><Button icon={<Pencil size={17} />} onClick={save}>{editing?.id ? 'Salva modifiche' : 'Crea impegno'}</Button></div></div>}>
        {editing ? <div className="form-grid form-grid--2">
          <Field label="Titolo" className="field--wide"><input autoFocus value={editing.title} onChange={e => setEditing({ ...editing, title: e.target.value })} placeholder="Es. Dentista, allenamento, riunione…" /></Field>
          <Field label="Data"><input type="date" value={editing.date} onChange={e => setEditing({ ...editing, date: e.target.value })} /></Field>
          <Field label="Ora inizio"><input type="time" value={editing.time || ''} onChange={e => setEditing({ ...editing, time: e.target.value })} /></Field>
          <Field label="Ora fine"><input type="time" value={editing.endTime || ''} onChange={e => setEditing({ ...editing, endTime: e.target.value })} /></Field>
          <Field label="Partecipanti" className="field--wide" hint="Famiglia include automaticamente tutti i membri attivi.">
            <label className="toggle-row"><input type="checkbox" checked={editing.audience === 'family'} onChange={e => setEditing({ ...editing, audience: e.target.checked ? 'family' : 'users', userIds: e.target.checked ? data.users.map(user => user.id) : participantIds(editing) })} /><span>Tutta la famiglia</span></label>
            {editing.audience !== 'family' ? <div className="settings-check-grid" style={{ marginTop: 10 }}>{data.users.map(user => { const selected = participantIds(editing).includes(user.id); return <label key={user.id} className={selected ? 'is-selected' : ''}><input type="checkbox" checked={selected} onChange={() => toggleParticipant(user.id)} /><span>{user.name}</span></label> })}</div> : <div className="callout" style={{ marginTop: 10 }}>Questo evento sarà visibile a tutti i membri della famiglia. Con Google Calendar potrà usare il calendario condiviso configurato nelle Impostazioni.</div>}
          </Field>
          <Field label="Note" className="field--wide"><textarea rows={4} value={editing.notes || ''} onChange={e => setEditing({ ...editing, notes: e.target.value })} placeholder="Dettagli utili…" /></Field>
        </div> : null}
      </Modal>
    </div>
  )
}

import React, { useState } from 'react'
import { CheckCircle2, Clock3, Pencil, Plus, Repeat2, RotateCcw, Trash2, WalletCards, XCircle } from 'lucide-react'
import { useFamily } from '../store'
import { Avatar, Badge, Button, Card, CardHeader, EmptyState, Field, IconButton, Modal, PageIntro, Segmented } from '../ui'
import { localDateISO, money } from '../utils'

const WEEKDAYS = [
  { id: 1, label: 'Lun' },
  { id: 2, label: 'Mar' },
  { id: 3, label: 'Mer' },
  { id: 4, label: 'Gio' },
  { id: 5, label: 'Ven' },
  { id: 6, label: 'Sab' },
  { id: 7, label: 'Dom' }
]

function recurringLabel(days: number[]) {
  const sorted = [...(days || [])].map(Number).sort()
  if (sorted.length === 7) return 'Ogni giorno'
  if (sorted.join(',') === '1,2,3,4,5') return 'Lun–Ven'
  if (sorted.join(',') === '6,7') return 'Weekend'
  return WEEKDAYS.filter(day => sorted.includes(day.id)).map(day => day.label).join(', ')
}

function choreStatus(chore: any): 'open' | 'pending' | 'approved' {
  if (chore.done) return 'approved'
  return chore.completionStatus === 'pending' ? 'pending' : 'open'
}

export default function ChoresPage() {
  const {
    data,
    authUser,
    addChore,
    toggleChore,
    approveChore,
    rejectChore,
    deleteChore,
    upsertRecurringChore,
    toggleRecurringChore,
    deleteRecurringChore,
    payUser,
    undoTransaction
  } = useFamily()

  const isChild = authUser?.role === 'bimbo'
  const [tab, setTab] = useState<'chores' | 'recurring' | 'wallets'>('chores')
  const [editing, setEditing] = useState<any>(null)
  const [recurringEditing, setRecurringEditing] = useState<any>(null)
  const [payment, setPayment] = useState<any>(null)
  const showBalances = authUser?.prefs?.showBalances !== false

  const visibleUsers = isChild && authUser
    ? data.users.filter(user => user.id === authUser.id)
    : data.users
  const walletUsers = visibleUsers
  const pendingApprovalCount = data.chores.filter(chore => !chore.done && chore.completionStatus === 'pending').length

  function openNew() {
    if (isChild) return
    setEditing({ title: '', deadline: localDateISO(), userId: data.users[0]?.id || 1, amount: 1 })
  }

  function openRecurring(item?: any) {
    if (isChild) return
    setRecurringEditing(item
      ? { ...item, weekdays: [...(item.weekdays || [])] }
      : {
          title: '',
          userId: data.users[0]?.id || 1,
          amount: 1,
          weekdays: [1, 2, 3, 4, 5, 6, 7],
          active: true,
          startDate: localDateISO(),
          endDate: ''
        })
  }

  function saveChore() {
    if (!editing?.title?.trim() || isChild) return
    addChore({
      title: editing.title.trim(),
      deadline: editing.deadline,
      userId: Number(editing.userId),
      amount: Math.max(0, Number(editing.amount) || 0)
    })
    setEditing(null)
  }

  function saveRecurring() {
    if (isChild || !recurringEditing?.title?.trim() || !recurringEditing?.weekdays?.length) return
    upsertRecurringChore({
      id: recurringEditing.id,
      title: recurringEditing.title.trim(),
      userId: Number(recurringEditing.userId),
      amount: Math.max(0, Number(recurringEditing.amount) || 0),
      weekdays: recurringEditing.weekdays.map(Number),
      active: recurringEditing.active !== false,
      startDate: recurringEditing.startDate || localDateISO(),
      endDate: recurringEditing.endDate || undefined
    })
    setRecurringEditing(null)
  }

  function toggleRecurringDay(day: number) {
    if (!recurringEditing || isChild) return
    const days = recurringEditing.weekdays || []
    setRecurringEditing({
      ...recurringEditing,
      weekdays: days.includes(day) ? days.filter((item: number) => item !== day) : [...days, day].sort()
    })
  }

  function submitPayment() {
    if (isChild) return
    const amount = Number(payment?.amount) || 0
    if (!payment || amount <= 0) return
    if (payUser(payment.userId, amount, payment.note || 'Pagamento paghetta')) setPayment(null)
  }

  const introAction = isChild
    ? null
    : tab === 'recurring'
      ? <Button icon={<Repeat2 size={18} />} onClick={() => openRecurring()}>Nuovo ricorrente</Button>
      : tab === 'chores'
        ? <Button icon={<Plus size={18} />} onClick={openNew}>Nuovo compito</Button>
        : null

  const tabs = isChild
    ? [
        { value: 'chores', label: `I miei compiti · ${data.chores.filter(c => c.userId === authUser?.id && !c.done).length}` },
        { value: 'wallets', label: 'La mia paghetta' }
      ]
    : [
        { value: 'chores', label: `Compiti · ${data.chores.filter(c => !c.done).length}${pendingApprovalCount ? ` · ${pendingApprovalCount} da confermare` : ''}` },
        { value: 'recurring', label: `Ricorrenti · ${data.recurringChores.filter(c => c.active).length}` },
        { value: 'wallets', label: 'Paghette & movimenti' }
      ]

  return <div className="page">
    <PageIntro
      eyebrow="Responsabilità"
      title="Compiti & paghette"
      description={isChild
        ? 'Segna i tuoi compiti come fatti. La paghetta viene accreditata dopo la conferma di un genitore.'
        : 'I ragazzi segnalano i compiti completati; un adulto li verifica e approva prima dell’accredito.'}
      actions={introAction}
    />

    {!isChild && pendingApprovalCount > 0 ? <div className="approval-banner">
      <Clock3 size={18} />
      <div>
        <strong>{pendingApprovalCount} {pendingApprovalCount === 1 ? 'compito aspetta' : 'compiti aspettano'} la tua conferma</strong>
        <span>La paghetta non è ancora stata accreditata.</span>
      </div>
    </div> : null}

    <div className="page-tabs-wrap">
      <Segmented
        value={isChild && tab === 'recurring' ? 'chores' : tab}
        onChange={setTab}
        options={tabs}
      />
    </div>

    {(tab === 'chores' || (isChild && tab === 'recurring')) ? <div className="chores-grid">{visibleUsers.map(user => {
      const chores = data.chores.filter(c => c.userId === user.id)
      const openCount = chores.filter(c => !c.done && c.completionStatus !== 'pending').length
      const waitingCount = chores.filter(c => !c.done && c.completionStatus === 'pending').length
      const subtitle = isChild
        ? `${openCount} da fare${waitingCount ? ` · ${waitingCount} in attesa` : ''}`
        : `${openCount} da fare${waitingCount ? ` · ${waitingCount} da confermare` : ''}`

      return <Card key={user.id}>
        <CardHeader
          title={<span className="user-heading"><Avatar user={user} size="sm" />{user.name}</span>}
          subtitle={subtitle}
        />
        {chores.length ? <div className="check-list">
          {chores
            .slice()
            .sort((a, b) => {
              const order = { pending: 0, open: 1, approved: 2 }
              const byStatus = order[choreStatus(a)] - order[choreStatus(b)]
              return byStatus || a.deadline.localeCompare(b.deadline)
            })
            .map(chore => {
              const status = choreStatus(chore)
              const isPending = status === 'pending'
              const isApproved = status === 'approved'
              const canChildToggle = isChild && chore.userId === authUser?.id && !isApproved
              const childActionText = isPending ? 'Tocca per annullare la richiesta' : 'Tocca quando hai finito'

              return <div key={chore.id} className={`check-item chore-item chore-item--${status} ${isApproved ? 'is-done' : ''}`}>
                <button
                  className="check-item__check"
                  onClick={() => {
                    if (isChild) {
                      if (canChildToggle) toggleChore(chore.id)
                    } else if (!isPending) {
                      toggleChore(chore.id)
                    }
                  }}
                  disabled={isChild ? !canChildToggle : isPending}
                  title={isChild ? childActionText : isPending ? 'Usa Conferma o Rifiuta' : isApproved ? 'Riapri compito' : 'Segna e approva'}
                >
                  {isApproved ? <CheckCircle2 size={16} /> : isPending ? <Clock3 size={15} /> : null}
                </button>

                <button
                  className="check-item__copy"
                  onClick={() => {
                    if (isChild && canChildToggle) toggleChore(chore.id)
                  }}
                  disabled={!isChild || !canChildToggle}
                >
                  <strong>{chore.title}</strong>
                  <span>
                    {chore.deadline} · {money(chore.amount)}
                    {chore.recurringChoreId ? ' · Ricorrente' : ''}
                  </span>
                  <small className={`chore-status chore-status--${status}`}>
                    {isPending
                      ? (isChild ? '✓ Segnalato come fatto · attende un genitore' : 'Da verificare e confermare')
                      : isApproved
                        ? '✓ Approvato · paghetta accreditata'
                        : (isChild ? 'Da fare · segnalo io quando ho finito' : 'Da fare')}
                  </small>
                </button>

                {!isChild && isPending ? <div className="chore-approval-actions">
                  <Button size="sm" variant="soft" onClick={() => approveChore(chore.id)}>Conferma</Button>
                  <IconButton label="Rifiuta e riapri" onClick={() => rejectChore(chore.id)}><XCircle size={17} /></IconButton>
                </div> : null}

                {!isChild && !isPending ? <IconButton label="Elimina" onClick={() => deleteChore(chore.id)}><Trash2 size={17} /></IconButton> : null}
              </div>
            })}
        </div> : <EmptyState
          icon={<CheckCircle2 size={28} />}
          title="Tutto fatto"
          text={isChild ? 'Non hai compiti assegnati.' : 'Nessun compito assegnato.'}
        />}
      </Card>
    })}</div> : null}

    {!isChild && tab === 'recurring' ? <div className="recurring-grid">
      {data.users.map(user => {
        const recurring = data.recurringChores.filter(item => item.userId === user.id)
        return <Card key={user.id}>
          <CardHeader
            title={<span className="user-heading"><Avatar user={user} size="sm" />{user.name}</span>}
            subtitle={`${recurring.filter(item => item.active).length} attivi`}
          />
          {recurring.length ? <div className="recurring-list">
            {recurring.map(item => <div key={item.id} className={`recurring-row ${item.active ? '' : 'is-disabled'}`}>
              <label className="recurring-switch" title={item.active ? 'Disattiva' : 'Attiva'}>
                <input type="checkbox" checked={item.active} onChange={() => toggleRecurringChore(item.id)} />
              </label>
              <button className="recurring-row__copy" onClick={() => openRecurring(item)}>
                <strong>{item.title}</strong>
                <span>{recurringLabel(item.weekdays)} · {money(item.amount)} per completamento</span>
                {(item.startDate || item.endDate) ? <small>
                  Dal {item.startDate || '—'}{item.endDate ? ` al ${item.endDate}` : ''}
                </small> : null}
              </button>
              <Badge tone={item.active ? 'success' : 'neutral'}>{item.active ? 'Attivo' : 'Pausa'}</Badge>
              <IconButton label="Modifica" onClick={() => openRecurring(item)}><Pencil size={16} /></IconButton>
              <IconButton label="Elimina ricorrenza" onClick={() => deleteRecurringChore(item.id)}><Trash2 size={16} /></IconButton>
            </div>)}
          </div> : <EmptyState
            icon={<Repeat2 size={28} />}
            title="Nessun compito ricorrente"
            text="Crea attività abituali come apparecchiare, rifare il letto o sistemare la camera e assegna una paghetta fissa."
            action={<Button variant="soft" onClick={() => openRecurring()}>Crea il primo</Button>}
          />}
        </Card>
      })}
    </div> : null}

    {tab === 'wallets' ? <div className="wallet-layout">
      <div className="wallet-grid">{walletUsers.map(user => <Card key={user.id} className="wallet-card">
        <div className="wallet-card__head">
          <Avatar user={user} size="lg" />
          <div>
            <span>{user.name}</span>
            <strong>{showBalances ? money(user.balance) : '••••'}</strong>
            {isChild ? <small>Disponibile dopo l’approvazione dei compiti</small> : null}
          </div>
        </div>
        {!isChild ? <Button
          variant="soft"
          onClick={() => setPayment({ userId: user.id, amount: user.balance, note: 'Pagamento paghetta' })}
          disabled={user.balance <= 0}
        >
          Registra pagamento
        </Button> : null}
      </Card>)}</div>

      <Card>
        <CardHeader
          title={isChild ? 'I miei movimenti' : 'Movimenti'}
          subtitle={isChild ? 'Accrediti approvati e pagamenti registrati.' : 'I pagamenti errati possono essere annullati.'}
        />
        {data.transactions.filter(tx => !isChild || tx.userId === authUser?.id).length ? <div className="transaction-list">
          {data.transactions
            .filter(tx => !isChild || tx.userId === authUser?.id)
            .slice()
            .sort((a, b) => b.id - a.id)
            .map(tx => {
              const user = data.users.find(u => u.id === tx.userId)
              return <div key={tx.id} className={`transaction-row ${tx.reversed ? 'is-reversed' : ''}`}>
                <Avatar user={user} size="xs" />
                <div><strong>{tx.note}</strong><span>{tx.date} · {user?.name}</span></div>
                <Badge tone={tx.type === 'credit' ? 'success' : tx.type === 'payment' ? 'warning' : 'neutral'}>
                  {tx.type === 'credit' ? '+' : '-'}{money(tx.amount)}
                </Badge>
                {!isChild && tx.type === 'payment' && !tx.reversed
                  ? <IconButton label="Annulla pagamento" onClick={() => undoTransaction(tx.id)}><RotateCcw size={17} /></IconButton>
                  : tx.reversed ? <Badge>Annullato</Badge> : null}
              </div>
            })}
        </div> : <EmptyState icon={<WalletCards size={28} />} title="Nessun movimento" text="Qui appariranno accrediti e pagamenti." />}
      </Card>
    </div> : null}

    {!isChild ? <Modal
      open={!!editing}
      onClose={() => setEditing(null)}
      title="Nuovo compito"
      footer={<div className="modal-actions"><span /><div className="modal-actions__right">
        <Button variant="ghost" onClick={() => setEditing(null)}>Annulla</Button>
        <Button onClick={saveChore}>Assegna</Button>
      </div></div>}
    >
      {editing ? <div className="form-grid form-grid--2">
        <Field label="Compito" className="field--wide">
          <input autoFocus value={editing.title} onChange={e => setEditing({ ...editing, title: e.target.value })} placeholder="Es. Sistemare la camera" />
        </Field>
        <Field label="Scadenza">
          <input type="date" value={editing.deadline} onChange={e => setEditing({ ...editing, deadline: e.target.value })} />
        </Field>
        <Field label="Assegna a">
          <select value={editing.userId} onChange={e => setEditing({ ...editing, userId: Number(e.target.value) })}>
            {data.users.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
          </select>
        </Field>
        <Field label="Compenso">
          <input type="number" min="0" step="0.1" value={editing.amount} onChange={e => setEditing({ ...editing, amount: Number(e.target.value) })} />
        </Field>
      </div> : null}
    </Modal> : null}

    {!isChild ? <Modal
      open={!!recurringEditing}
      onClose={() => setRecurringEditing(null)}
      title={recurringEditing?.id ? 'Modifica compito ricorrente' : 'Nuovo compito ricorrente'}
      subtitle="L’importo viene accreditato solo dopo la conferma di un adulto."
      footer={<div className="modal-actions"><span /><div className="modal-actions__right">
        <Button variant="ghost" onClick={() => setRecurringEditing(null)}>Annulla</Button>
        <Button onClick={saveRecurring} disabled={!recurringEditing?.weekdays?.length}>Salva</Button>
      </div></div>}
    >
      {recurringEditing ? <div className="form-grid form-grid--2">
        <Field label="Compito" className="field--wide">
          <input
            autoFocus
            value={recurringEditing.title}
            onChange={e => setRecurringEditing({ ...recurringEditing, title: e.target.value })}
            placeholder="Es. Apparecchiare"
          />
        </Field>
        <Field label="Assegna a">
          <select value={recurringEditing.userId} onChange={e => setRecurringEditing({ ...recurringEditing, userId: Number(e.target.value) })}>
            {data.users.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
          </select>
        </Field>
        <Field label="Paghetta dopo approvazione">
          <input
            type="number"
            min="0"
            step="0.1"
            value={recurringEditing.amount}
            onChange={e => setRecurringEditing({ ...recurringEditing, amount: Number(e.target.value) })}
          />
        </Field>
        <Field label="Dal">
          <input type="date" value={recurringEditing.startDate || ''} onChange={e => setRecurringEditing({ ...recurringEditing, startDate: e.target.value })} />
        </Field>
        <Field label="Fino al" hint="Facoltativo">
          <input type="date" min={recurringEditing.startDate || undefined} value={recurringEditing.endDate || ''} onChange={e => setRecurringEditing({ ...recurringEditing, endDate: e.target.value })} />
        </Field>
        <Field label="Giorni" className="field--wide" hint="Seleziona uno o più giorni della settimana">
          <div className="weekday-picker">
            {WEEKDAYS.map(day => <button
              type="button"
              key={day.id}
              className={recurringEditing.weekdays?.includes(day.id) ? 'is-active' : ''}
              onClick={() => toggleRecurringDay(day.id)}
            >
              {day.label}
            </button>)}
          </div>
          <div className="recurring-presets">
            <button type="button" onClick={() => setRecurringEditing({ ...recurringEditing, weekdays: [1, 2, 3, 4, 5, 6, 7] })}>Tutti i giorni</button>
            <button type="button" onClick={() => setRecurringEditing({ ...recurringEditing, weekdays: [1, 2, 3, 4, 5] })}>Lun–Ven</button>
            <button type="button" onClick={() => setRecurringEditing({ ...recurringEditing, weekdays: [6, 7] })}>Weekend</button>
          </div>
        </Field>
        <label className="toggle-row field--wide">
          <input
            type="checkbox"
            checked={recurringEditing.active !== false}
            onChange={e => setRecurringEditing({ ...recurringEditing, active: e.target.checked })}
          />
          Attivo: genera automaticamente il compito nei giorni selezionati
        </label>
      </div> : null}
    </Modal> : null}

    {!isChild ? <Modal
      open={!!payment}
      onClose={() => setPayment(null)}
      title="Registra pagamento"
      subtitle={payment ? data.users.find(u => u.id === payment.userId)?.name : ''}
      footer={<div className="modal-actions"><span /><div className="modal-actions__right">
        <Button variant="ghost" onClick={() => setPayment(null)}>Annulla</Button>
        <Button onClick={submitPayment}>Conferma pagamento</Button>
      </div></div>}
    >
      {payment ? <div className="form-grid">
        <Field label="Importo"><input type="number" min="0" step="0.1" value={payment.amount} onChange={e => setPayment({ ...payment, amount: Number(e.target.value) })} /></Field>
        <Field label="Nota"><input value={payment.note} onChange={e => setPayment({ ...payment, note: e.target.value })} /></Field>
      </div> : null}
    </Modal> : null}
  </div>
}

import React, { useMemo, useState } from 'react'
import {
  AlertTriangle,
  CalendarDays,
  CheckCircle2,
  ChevronRight,
  Clock3,
  GraduationCap,
  ListTodo,
  Pin,
  Plus,
  ReceiptText,
  ShoppingCart,
  Users,
  Utensils,
  WalletCards
} from 'lucide-react'
import { useFamily } from '../store'
import { Card, CardHeader, EmptyState, ListRow, PageIntro, StatCard } from '../ui'
import { addDays, dayLabel, localDateISO, money, pantryExpiryDays, pantryNeedsRestock, routineCompletedOn, routineDueOn, weekDates } from '../utils'
import './dashboard-command-center.css'

type HomeView = 'today' | 'week' | 'family'

function shortDate(date: string) {
  return `${date.slice(8, 10)}/${date.slice(5, 7)}`
}

export default function Dashboard() {
  const { data, authUser, setActivePage } = useFamily()
  const [homeView, setHomeView] = useState<HomeView>('today')
  const today = localDateISO()
  const week = weekDates(today)
  const weekEnd = week[week.length - 1] || addDays(today, 6)

  const eventsToday = useMemo(
    () => data.calendarEvents.filter(e => e.date === today).sort((a, b) => (a.time || '').localeCompare(b.time || '')),
    [data.calendarEvents, today]
  )

  const nextDeadlines = useMemo(
    () => data.deadlines
      .filter(d => d.kind !== 'medicine' && d.kind !== 'therapy' && !d.done && d.date >= today && d.date <= addDays(today, 15))
      .sort((a, b) => a.date.localeCompare(b.date))
      .slice(0, 5),
    [data.deadlines, today]
  )

  const tomorrow = addDays(today, 1)
  const schoolTomorrow = data.schoolItems
    .filter(item => !item.done && item.date === tomorrow)
    .filter(item => authUser?.role !== 'bimbo' || item.userId === authUser.id)
  const schoolTomorrowLessons = data.schoolTimetable
    .filter(entry => entry.weekday === (() => { const day = new Date(`${tomorrow}T12:00:00`).getDay(); return day === 0 ? 7 : day })())
    .filter(entry => authUser?.role !== 'bimbo' || entry.userId === authUser.id)

  const boardVisible = data.boardPosts
    .filter(post => post.authorUserId === authUser?.id || post.audience === 'family' || (post.userIds || []).includes(authUser?.id || 0))
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
  const pinnedBoard = boardVisible.filter(post => post.pinned)
  const boardDueSoon = boardVisible.filter(post => post.type === 'reminder' && post.dueDate && post.dueDate >= today && post.dueDate <= tomorrow)

  const pendingShopping = data.shopping.filter(x => !x.taken)
  const pendingChores = data.chores.filter(x => !x.done)
  const choresAwaitingApproval = data.chores.filter(x => !x.done && x.completionStatus === 'pending')
  const choresStillToDo = pendingChores.filter(x => x.completionStatus !== 'pending')
  const pendingTodos = data.todos.filter(x => !x.done)
  const dueRoutinesToday = data.routines.filter(routine =>
    routineDueOn(routine, today) && !routineCompletedOn(data.routineCompletions, routine.id, today)
  )
  const lowStock = data.pantry.filter(item => pantryNeedsRestock(item, data.pantryMovements, today))
  const expiringInventory = data.pantry
    .map(item => ({ item, days: pantryExpiryDays(item, today) }))
    .filter(entry => entry.days !== null && entry.days <= 3)

  const eventsByDate = useMemo(() => {
    const map: Record<string, typeof data.calendarEvents> = {}
    for (const date of week) map[date] = []
    for (const event of data.calendarEvents) {
      if (!map[event.date]) continue
      map[event.date].push(event)
    }
    Object.values(map).forEach(items => items.sort((a, b) => (a.time || '').localeCompare(b.time || '')))
    return map
  }, [data.calendarEvents, week.join('|')])

  const mealByDate = useMemo(() => {
    const map: Record<string, Array<{ name: string; slot: string; userId: number }>> = {}
    for (const date of week) map[date] = []
    for (const plan of data.mealPlans) {
      if (!map[plan.date]) continue
      const dish = data.dishes.find(d => d.id === plan.dishId)
      if (!dish) continue
      map[plan.date].push({
        name: dish.variant ? `${dish.name} · ${dish.variant}` : dish.name,
        slot: plan.slot,
        userId: plan.userId
      })
    }
    return map
  }, [data.mealPlans, data.dishes, week.join('|')])

  const routinesByDate = useMemo(() => {
    const map: Record<string, typeof data.routines> = {}
    for (const date of week) map[date] = []
    for (const date of week) {
      map[date] = data.routines.filter(routine =>
        routineDueOn(routine, date) && !routineCompletedOn(data.routineCompletions, routine.id, date)
      )
    }
    return map
  }, [data.routines, data.routineCompletions, week.join('|')])

  const deadlinesByDate = useMemo(() => {
    const map: Record<string, typeof data.deadlines> = {}
    for (const date of week) map[date] = []
    for (const deadline of data.deadlines) {
      if (!deadline.done && map[deadline.date] && deadline.kind !== 'medicine' && deadline.kind !== 'therapy') map[deadline.date].push(deadline)
    }
    return map
  }, [data.deadlines, week.join('|')])

  const choresByDate = useMemo(() => {
    const map: Record<string, typeof data.chores> = {}
    for (const date of week) map[date] = []
    for (const chore of data.chores) {
      if (!chore.done && map[chore.deadline]) map[chore.deadline].push(chore)
    }
    return map
  }, [data.chores, week.join('|')])

  const showBalances = authUser?.prefs?.showBalances !== false
  const totalBalance = data.users.reduce((sum, u) => sum + Number(u.balance || 0), 0)

  function participantNames(event: any) {
    if (event.audience === 'family') return 'Famiglia'
    const ids: number[] = event.userIds?.length ? event.userIds : [event.userId]
    const names = ids.map(id => data.users.find(user => user.id === id)?.name).filter(Boolean)
    return names.join(', ') || 'Famiglia'
  }

  function eventForUser(event: any, userId: number) {
    if (event.audience === 'family') return true
    const ids: number[] = event.userIds?.length ? event.userIds : [event.userId]
    return ids.includes(userId)
  }

  const familyCards = useMemo(() => data.users.map(user => {
    const weekEvents = data.calendarEvents
      .filter(event => event.date >= today && event.date <= weekEnd && eventForUser(event, user.id))
      .sort((a, b) => `${a.date}${a.time || ''}`.localeCompare(`${b.date}${b.time || ''}`))
    const userTodos = pendingTodos.filter(item => item.userId === user.id)
    const userRoutines = week.flatMap(date => (routinesByDate[date] || []).filter(item => item.userId === user.id))
    const userChores = pendingChores.filter(item => item.userId === user.id)
    const userDeadlines = data.deadlines
      .filter(item => !item.done && item.userId === user.id && item.date >= today && item.date <= weekEnd && item.kind !== 'medicine' && item.kind !== 'therapy')
      .sort((a, b) => a.date.localeCompare(b.date))
    return { user, weekEvents, userTodos, userRoutines, userChores, userDeadlines }
  }), [data.users, data.calendarEvents, data.deadlines, pendingTodos, pendingChores, routinesByDate, week.join('|'), today, weekEnd])

  const familyAlerts = [
    pendingShopping.length ? { label: `${pendingShopping.length} articoli da comprare`, page: 'shopping' as const } : null,
    lowStock.length ? { label: `${lowStock.length} prodotti da reintegrare`, page: 'shopping' as const } : null,
    expiringInventory.length ? { label: `${expiringInventory.length} prodotti in scadenza`, page: 'shopping' as const } : null,
    nextDeadlines.length ? { label: `${nextDeadlines.length} scadenze nei prossimi 15 giorni`, page: 'deadlines' as const } : null,
    pendingTodos.length ? { label: `${pendingTodos.length} promemoria aperti`, page: 'todos' as const } : null,
    dueRoutinesToday.length ? { label: `${dueRoutinesToday.length} routine da fare oggi`, page: 'todos' as const } : null,
    schoolTomorrow.length ? { label: `${schoolTomorrow.length} cose di scuola da preparare per domani`, page: 'school' as const } : null,
    boardDueSoon.length ? { label: `${boardDueSoon.length} promemoria in bacheca tra oggi e domani`, page: 'board' as const } : null,
    authUser?.role !== 'bimbo' && choresAwaitingApproval.length ? { label: `${choresAwaitingApproval.length} compiti da confermare`, page: 'chores' as const } : null
  ].filter(Boolean) as Array<{ label: string; page: any }>

  return (
    <div className="page page--dashboard command-center">
      <div className="command-center__topline">
        <PageIntro
          eyebrow={dayLabel(today, true)}
          title={`Ciao ${authUser?.name || ''} 👋`}
          description="Il centro operativo della famiglia: oggi, settimana e situazione di tutti in un solo posto."
        />
        <div className="home-view-switch" role="tablist" aria-label="Vista Home">
          <button className={homeView === 'today' ? 'is-active' : ''} onClick={() => setHomeView('today')}>Oggi</button>
          <button className={homeView === 'week' ? 'is-active' : ''} onClick={() => setHomeView('week')}>Settimana</button>
          <button className={homeView === 'family' ? 'is-active' : ''} onClick={() => setHomeView('family')}>Famiglia</button>
        </div>
      </div>

      <div className="quick-actions" aria-label="Azioni rapide">
        <button onClick={() => setActivePage('calendar')}><CalendarDays size={18} /><span>Nuovo impegno</span><Plus size={16} /></button>
        <button onClick={() => setActivePage('shopping')}><ShoppingCart size={18} /><span>Aggiungi spesa</span><Plus size={16} /></button>
        <button onClick={() => setActivePage('meals')}><Utensils size={18} /><span>Pianifica pasto</span><Plus size={16} /></button>
        <button onClick={() => setActivePage('todos')}><ListTodo size={18} /><span>Da fare</span><Plus size={16} /></button>
        <button onClick={() => setActivePage('school')}><GraduationCap size={18} /><span>Scuola</span><ChevronRight size={16} /></button>
        <button onClick={() => setActivePage('board')}><Pin size={18} /><span>Bacheca</span><ChevronRight size={16} /></button>
      </div>

      {homeView === 'today' ? <>
        <div className="stats-grid command-stats">
          <StatCard icon={<Clock3 size={20} />} label="Impegni oggi" value={eventsToday.length} note={eventsToday[0] ? `${eventsToday[0].time || 'Tutto il giorno'} · ${eventsToday[0].title}` : 'Nessun impegno'} onClick={() => setActivePage('calendar')} />
          <StatCard icon={<ShoppingCart size={20} />} label="Da comprare" value={pendingShopping.length} note={pendingShopping[0]?.name || 'Lista vuota'} onClick={() => setActivePage('shopping')} tone="mint" />
          <StatCard icon={<ReceiptText size={20} />} label="Scadenze" value={nextDeadlines.length} note={nextDeadlines[0] ? `${shortDate(nextDeadlines[0].date)} · ${nextDeadlines[0].title}` : 'Tutto in ordine'} onClick={() => setActivePage('deadlines')} tone="amber" />
          <StatCard icon={<WalletCards size={20} />} label="Paghette" value={showBalances ? money(totalBalance) : '••••'} note={authUser?.role !== 'bimbo' && choresAwaitingApproval.length ? `${choresAwaitingApproval.length} da confermare · ${choresStillToDo.length} da fare` : `${choresStillToDo.length} compiti da completare`} onClick={() => setActivePage('chores')} tone="violet" />
        </div>

        <div className="command-grid command-grid--today">
          <Card className="command-panel command-panel--agenda">
            <CardHeader title="Agenda di oggi" subtitle="Tutti gli impegni in ordine" action={<button className="text-link" onClick={() => setActivePage('calendar')}>Calendario <ChevronRight size={16} /></button>} />
            {eventsToday.length ? <div className="timeline-list">
              {eventsToday.slice(0, 7).map(event => <ListRow key={event.id} leading={<span className="time-pill">{event.time || '—'}</span>} title={event.title} subtitle={participantNames(event)} trailing={<ChevronRight size={17} />} onClick={() => setActivePage('calendar')} />)}
            </div> : <EmptyState icon={<CalendarDays size={28} />} title="Giornata libera" text="Nessun impegno previsto per oggi." />}
          </Card>

          <Card className="command-panel">
            <CardHeader title="Pasti di oggi" subtitle="Pranzo e cena pianificati" action={<button className="text-link" onClick={() => setActivePage('meals')}>Pasti <ChevronRight size={16} /></button>} />
            {(mealByDate[today] || []).length ? <div className="command-simple-list">{mealByDate[today].map((meal, index) => <button key={`${meal.slot}-${index}`} onClick={() => setActivePage('meals')}><Utensils size={17} /><span><strong>{meal.slot}</strong><small>{meal.name}</small></span></button>)}</div> : <EmptyState icon={<Utensils size={28} />} title="Pasti non pianificati" text="Puoi aggiungere pranzo e cena dal planner pasti." />}
          </Card>

          <Card className="command-panel">
            <CardHeader title="Scuola · domani" subtitle="Lezioni e cose da preparare" action={<button className="text-link" onClick={() => setActivePage('school')}>Scuola <ChevronRight size={16} /></button>} />
            {schoolTomorrow.length || schoolTomorrowLessons.length ? <div className="command-simple-list">
              {schoolTomorrow.slice(0, 4).map(item => <button key={`school-${item.id}`} onClick={() => setActivePage('school')}><GraduationCap size={17} /><span><strong>{item.title}</strong><small>{data.users.find(u => u.id === item.userId)?.name || 'Scuola'}</small></span></button>)}
              {schoolTomorrow.length === 0 && schoolTomorrowLessons.length ? <button onClick={() => setActivePage('school')}><GraduationCap size={17} /><span><strong>{schoolTomorrowLessons.length} lezioni previste</strong><small>Controlla orario e zaino</small></span></button> : null}
            </div> : <EmptyState icon={<GraduationCap size={28} />} title="Niente da preparare" text="Nessun impegno scolastico registrato per domani." />}
          </Card>

          <Card className="command-panel command-panel--board">
            <CardHeader title="Bacheca" subtitle="Messaggi fissati per la famiglia" action={<button className="text-link" onClick={() => setActivePage('board')}>Apri <ChevronRight size={16} /></button>} />
            {pinnedBoard.length ? <div className="home-board-list">
              {pinnedBoard.slice(0, 3).map(post => <button key={post.id} onClick={() => setActivePage('board')}>
                <Pin size={16} />
                <span><strong>{post.title || post.body.slice(0, 55) || 'Contenuto fissato'}</strong><small>{post.body && post.title ? post.body.slice(0, 80) : post.type === 'reminder' && post.dueDate ? `Promemoria · ${shortDate(post.dueDate)}` : 'Bacheca familiare'}</small></span>
                <ChevronRight size={15} />
              </button>)}
            </div> : boardDueSoon.length ? <div className="home-board-list">
              {boardDueSoon.slice(0, 3).map(post => <button key={post.id} onClick={() => setActivePage('board')}>
                <Pin size={16} />
                <span><strong>{post.title || post.body.slice(0, 55) || 'Promemoria'}</strong><small>{post.dueDate ? `Per ${shortDate(post.dueDate)}` : 'Bacheca familiare'}</small></span>
                <ChevronRight size={15} />
              </button>)}
            </div> : <EmptyState icon={<Pin size={28} />} title="Niente in evidenza" text="Fissa un messaggio o un promemoria per averlo sempre qui sul tablet." />}
          </Card>

          <Card className="command-panel">
            <CardHeader title="Da fare" subtitle="Attività ancora aperte" action={<button className="text-link" onClick={() => setActivePage('todos')}>Tutte <ChevronRight size={16} /></button>} />
            {pendingTodos.length || dueRoutinesToday.length || pendingChores.length ? <div className="command-simple-list">
              {dueRoutinesToday.slice(0, 2).map(item => <button key={`routine-${item.id}`} onClick={() => setActivePage('todos')}><ListTodo size={17} /><span><strong>{item.title}</strong><small>Routine · {data.users.find(u => u.id === item.userId)?.name || 'Famiglia'}</small></span></button>)}
              {pendingTodos.slice(0, 2).map(item => <button key={`todo-${item.id}`} onClick={() => setActivePage('todos')}><ListTodo size={17} /><span><strong>{item.title}</strong><small>{data.users.find(u => u.id === item.userId)?.name || 'Famiglia'}</small></span></button>)}
              {pendingChores.slice(0, 2).map(item => <button key={`chore-${item.id}`} onClick={() => setActivePage('chores')}><CheckCircle2 size={17} /><span><strong>{item.title}</strong><small>{data.users.find(u => u.id === item.userId)?.name || 'Famiglia'} · entro {shortDate(item.deadline)}</small></span></button>)}
            </div> : <EmptyState icon={<CheckCircle2 size={28} />} title="Tutto fatto" text="Non risultano attività aperte." />}
          </Card>

          <Card className="command-panel command-panel--alerts">
            <CardHeader title="Avvisi" subtitle="Quello che richiede attenzione" />
            {familyAlerts.length ? <div className="command-alerts">{familyAlerts.map((alert, index) => <button key={index} onClick={() => setActivePage(alert.page)}><AlertTriangle size={17} /><span>{alert.label}</span><ChevronRight size={16} /></button>)}</div> : <EmptyState icon={<CheckCircle2 size={28} />} title="Nessun avviso" text="La situazione della famiglia è sotto controllo." />}
          </Card>
        </div>
      </> : null}

      {homeView === 'week' ? <div className="week-command-view">
        <div className="week-command-heading">
          <div><span className="eyebrow">Planner familiare</span><h2>La settimana in un colpo d’occhio</h2><p>Agenda, pasti, attività e scadenze raccolti giorno per giorno.</p></div>
          <button className="week-command-heading__calendar" onClick={() => setActivePage('calendar')}><CalendarDays size={18} /> Apri calendario</button>
        </div>
        <div className="week-command-grid">
          {week.map(date => {
            const events = eventsByDate[date] || []
            const meals = mealByDate[date] || []
            const deadlines = deadlinesByDate[date] || []
            const chores = choresByDate[date] || []
            const routines = routinesByDate[date] || []
            return <section key={date} className={`week-command-day ${date === today ? 'is-today' : ''}`}>
              <header><span>{dayLabel(date)}</span><strong>{date.slice(8, 10)}</strong>{date === today ? <small>Oggi</small> : null}</header>
              <div className="week-command-day__section">
                <label><CalendarDays size={15} /> Agenda</label>
                {events.length ? events.slice(0, 3).map(event => <button key={event.id} onClick={() => setActivePage('calendar')}><span>{event.time || '—'}</span><strong>{event.title}</strong></button>) : <em>Nessun impegno</em>}
                {events.length > 3 ? <small>+{events.length - 3} altri</small> : null}
              </div>
              <div className="week-command-day__section">
                <label><Utensils size={15} /> Pasti</label>
                {meals.length ? meals.slice(0, 2).map((meal, index) => <button key={`${meal.slot}-${index}`} onClick={() => setActivePage('meals')}><span>{meal.slot}</span><strong>{meal.name}</strong></button>) : <em>Da pianificare</em>}
              </div>
              {(chores.length || routines.length || deadlines.length) ? <div className="week-command-day__flags">
                {routines.length ? <button onClick={() => setActivePage('todos')}><ListTodo size={14} /> {routines.length} routine</button> : null}
