    setLessonEditing(null)
  }

  function saveSubject() {
    if (isChild || !subjectEditing?.name?.trim()) return
    upsertSchoolSubject({
      id: subjectEditing.id,
      name: subjectEditing.name.trim(),
      shortName: subjectEditing.shortName?.trim() || undefined
