  const backupHealth = getBackupHealth(driveStatus)

  useEffect(() => {
    void refreshBackupStatus()
    void refreshGoogleCalendar()
    const params = new URLSearchParams(window.location.search)
    const googleResult = params.get('googleCalendar')
    if (googleResult === 'connected') setGoogleMessage('Google Calendar collegato. Scegli ora dove sincronizzare gli eventi.')
    if (googleResult === 'error') setGoogleMessage(`Collegamento Google non riuscito${params.get('reason') ? `: ${params.get('reason')}` : '.'}`)
    if (googleResult) window.history.replaceState({}, '', window.location.pathname)
  }, [familyId, cloudAuthenticated])

  useEffect(() => {
    if (!familyId || !cloudAuthenticated) return
    const timer = window.setInterval(() => {
      void refreshBackupStatus()
    }, BACKUP_REFRESH_MS)
    return () => window.clearInterval(timer)
  }, [familyId, cloudAuthenticated])

  if (!authUser || !prefs) return null

  async function refreshBackupStatus() {
    if (!supabase || !familyId || !cloudAuthenticated) {
      setDriveStatus(null)
      setBackupHistory([])
      return
    }
    setBackupLoading(true)
    try {
      const [statusResult, historyResult] = await Promise.all([
        supabase.rpc('get_drive_backup_status', { p_family_id: familyId }),
        supabase
          .from('family_backups')
          .select('id,revision,reason,created_at')
          .eq('family_id', familyId)
          .order('created_at', { ascending: false })
          .limit(10)
      ])

      if (!statusResult.error) {
        const row = Array.isArray(statusResult.data) ? statusResult.data[0] : statusResult.data
        setDriveStatus(row || null)
      }
      if (!historyResult.error) setBackupHistory((historyResult.data || []) as BackupHistoryItem[])
    } finally {
      setBackupLoading(false)
    }
  }

  async function callGoogleCalendar(action: string, extra: Record<string, any> = {}) {
    if (!supabase || !familyId) throw new Error('Cloud non disponibile.')
    const { data: result, error } = await supabase.functions.invoke('google-calendar-sync', { body: { action, familyId, ...extra } })
    if (error) throw new Error(error.message || 'Errore Google Calendar')
    if (result?.error) throw new Error(result.error)
    return result
  }

  async function refreshGoogleCalendar() {
    if (!supabase || !familyId || !cloudAuthenticated) {
      setGoogleStatus(null)
      setGoogleCalendars([])
      return
    }
    setGoogleBusy(true)
    try {
      const status = await callGoogleCalendar('status') as GoogleCalendarStatus
      setGoogleStatus(status)
      const connection = status?.connection
      setGoogleDraft({
        personalCalendarId: connection?.personalCalendarId || 'primary',
        familyCalendarId: connection?.familyCalendarId || '',
        familyEventTarget: connection?.familyEventTarget || 'personal'
      })
      if (status?.connected) {
        const result = await callGoogleCalendar('calendars')
        setGoogleCalendars(result?.calendars || [])
      } else setGoogleCalendars([])
    } catch (error: any) {
      setGoogleMessage(`Google Calendar: ${error?.message || 'stato non disponibile'}`)
    } finally {
      setGoogleBusy(false)
    }
  }

  async function connectGoogleCalendar() {
    setGoogleBusy(true)
    setGoogleMessage('')
    try {
      const result = await callGoogleCalendar('auth-url')
      if (!result?.url) throw new Error('URL di collegamento non disponibile.')
      window.location.assign(result.url)
    } catch (error: any) {
      setGoogleMessage(`Collegamento non riuscito: ${error?.message || 'errore sconosciuto'}`)
      setGoogleBusy(false)
    }
  }

  async function saveGoogleCalendarSettings() {
    if ((googleDraft.familyEventTarget === 'shared' || googleDraft.familyEventTarget === 'both') && !googleDraft.familyCalendarId) {
      setGoogleMessage('Scegli prima un calendario famiglia condiviso.')
      return
    }
    setGoogleBusy(true)
    setGoogleMessage('')
    try {
      await callGoogleCalendar('save-settings', googleDraft)
      setGoogleMessage('Impostazioni Google Calendar salvate e calendario sincronizzato.')
      await refreshGoogleCalendar()
    } catch (error: any) {
      setGoogleMessage(`Salvataggio non riuscito: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setGoogleBusy(false)
    }
  }

  async function syncGoogleCalendarNow() {
    setGoogleBusy(true)
    setGoogleMessage('')
    try {
      await syncNow()
      const result = await callGoogleCalendar('sync-all')
      setGoogleMessage(`Google Calendar sincronizzato${typeof result?.synced === 'number' ? `: ${result.synced} collegamenti evento aggiornati` : ''}.`)
    } catch (error: any) {
      setGoogleMessage(`Sincronizzazione non riuscita: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setGoogleBusy(false)
    }
  }

  async function disconnectGoogleCalendar() {
    if (!confirm('Scollegare il tuo account Google Calendar da VerdoFamily? Gli eventi già copiati su Google non vengono cancellati.')) return
    setGoogleBusy(true)
    setGoogleMessage('')
    try {
      await callGoogleCalendar('disconnect')
      setGoogleMessage('Account Google Calendar scollegato.')
      await refreshGoogleCalendar()
    } catch (error: any) {
      setGoogleMessage(`Scollegamento non riuscito: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setGoogleBusy(false)
    }
  }

  async function runDriveBackup() {
    if (!supabase || !familyId) return
    setBackupBusy(true)
    setMessage('')
    try {
      await syncNow()
      const { data: result, error } = await supabase.functions.invoke('google-drive-backup-runner', {
        body: { familyId }
      })
      if (error) {
        setMessage(`Backup Google Drive non riuscito: ${error.message}`)
      } else if (result?.ok) {
        const fileName = result?.results?.[0]?.fileName
        setMessage(fileName ? `Backup Google Drive creato: ${fileName}` : 'Backup Google Drive creato correttamente.')
      } else {
        setMessage(`Backup Google Drive non riuscito: ${result?.error || result?.results?.[0]?.error || 'errore sconosciuto'}`)
      }
      await refreshBackupStatus()
    } catch (error: any) {
      setMessage(`Backup Google Drive non riuscito: ${error?.message || 'errore sconosciuto'}`)
    } finally {
      setBackupBusy(false)
    }
  }

  async function restoreBackup(item: BackupHistoryItem) {
    if (!supabase) return
    if (!confirm(`Ripristinare il backup revisione ${item.revision} del ${formatDateTime(item.created_at)}? Prima del ripristino verrà salvata automaticamente anche la situazione attuale.`)) return
    setBackupBusy(true)
    setMessage('')
    try {
      const { error } = await supabase.rpc('restore_family_backup', { p_backup_id: item.id })
      if (error) {
        setMessage(`Ripristino non riuscito: ${error.message}`)
      } else {
        setMessage('Backup ripristinato. I dispositivi collegati si aggiorneranno automaticamente.')
        await refreshBackupStatus()
      }
    } finally {
      setBackupBusy(false)
    }
  }

  function setTheme(theme: ThemeMode) {
    updateCurrentPrefs({ theme })
  }

  function toggleBottomTab(key: PageKey) {
    const current = prefs.bottomTabs || []
    if (current.includes(key)) {
      if (current.length <= 1) return
      updateCurrentPrefs({ bottomTabs: current.filter(x => x !== key) })
      return
    }
    if (current.length >= 4) return
    updateCurrentPrefs({ bottomTabs: [...current, key] })
  }

  function moveTab(index: number, dir: -1 | 1) {
    const next = [...prefs.bottomTabs]
    const target = index + dir
    if (target < 0 || target >= next.length) return
    const [item] = next.splice(index, 1)
    next.splice(target, 0, item)
    updateCurrentPrefs({ bottomTabs: next })
  }

  function toggleHomeCard(key: typeof HOME_CARDS[number]['key']) {
    const current = prefs.homeCards || []
    if (current.includes(key)) {
      if (current.length <= 1) return
      updateCurrentPrefs({ homeCards: current.filter(x => x !== key) as any })
    } else {
      updateCurrentPrefs({ homeCards: [...current, key] as any })
    }
  }

  async function copyBackup() {
    const text = exportData()
    try {
      await navigator.clipboard.writeText(text)
      setMessage('Backup copiato negli appunti.')
    } catch {
      setImportText(text)
      setMessage('Copia manualmente il JSON qui sotto.')
    }
  }

  function downloadBackup() {
    const blob = new Blob([exportData()], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `verdofamily-backup-${new Date().toISOString().slice(0, 10)}.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  function doImport() {
    if (!importText.trim()) return
    if (importData(importText)) {
      setMessage('Backup importato correttamente.')
      setImportText('')
    } else {
      setMessage('Il file/JSON non è valido.')
    }
  }

  return <div className="page">
    <PageIntro eyebrow="Centro di controllo" title="Impostazioni" description="Poche aree chiare: il tuo spazio, l’uso quotidiano, le connessioni e la protezione dei dati." />

    <div className="settings-flow">
      <section className="settings-section">
        <div className="settings-section__head">
          <div><span>01</span><h2>Il tuo spazio</h2></div>
          <p>Profilo e aspetto: tutto ciò che riguarda come riconosci e visualizzi il tuo VerdoFamily.</p>
        </div>
        <Card className="settings-card--wide settings-unified-card">
          <div className="settings-unified-grid settings-unified-grid--identity">
            <section className="settings-subsection">
              <div className="settings-subsection__head"><div><strong>Profilo</strong><span>Nome e colore personale</span></div></div>
              <div className="settings-profile settings-profile--compact"><Avatar user={authUser} size="lg" /><div><strong>{authUser.name}</strong><span>{authUser.role}</span></div></div>
              <div className="form-grid form-grid--2">
                <Field label="Nome"><input value={authUser.name} onChange={e => updateCurrentProfile({ name: e.target.value })} /></Field>
                <Field label="Colore profilo"><input type="color" value={authUser.color} onChange={e => updateCurrentProfile({ color: e.target.value })} /></Field>
              </div>
            </section>

            <section className="settings-subsection">
              <div className="settings-subsection__head"><div><strong>Aspetto</strong><span>Tema, colore e densità</span></div></div>
              <Field label="Tema"><Segmented value={prefs.theme} onChange={setTheme} options={[{ value: 'system', label: 'Sistema' }, { value: 'light', label: 'Chiaro' }, { value: 'dark', label: 'Scuro' }]} /></Field>
              <div className="accent-grid accent-grid--compact">{ACCENTS.map(item => <button key={item.color} className={`accent-swatch ${prefs.accent === item.color ? 'is-active' : ''}`} onClick={() => updateCurrentPrefs({ accent: item.color })}><span style={{ background: item.color }} /> <strong>{item.name}</strong>{prefs.accent === item.color ? <Check size={15} /> : null}</button>)}</div>
              <div className="form-grid form-grid--2 settings-inline-fields">
                <Field label="Colore libero"><input type="color" value={prefs.accent} onChange={e => updateCurrentPrefs({ accent: e.target.value })} /></Field>
                <Field label="Densità"><Segmented value={prefs.density} onChange={(density: any) => updateCurrentPrefs({ density })} options={[{ value: 'comfortable', label: 'Comoda' }, { value: 'compact', label: 'Compatta' }]} /></Field>
              </div>
            </section>
          </div>
        </Card>
      </section>

      <section className="settings-section">
        <div className="settings-section__head">
          <div><span>02</span><h2>Uso quotidiano</h2></div>
          <p>Decidi cosa mostrare sul tablet di casa, cosa tenere a portata di mano e quali avvisi vuoi ricevere.</p>
        </div>
        <Card className="settings-card--wide settings-unified-card">
          <div className="settings-unified-grid settings-unified-grid--daily">
            <section className="settings-subsection">
              <div className="settings-subsection__head"><div><strong>Home</strong><span>Riepiloghi visibili a colpo d’occhio</span></div></div>
              <div className="settings-check-grid settings-check-grid--compact">{HOME_CARDS.map(item => <label key={item.key} className={prefs.homeCards.includes(item.key) ? 'is-selected' : ''}><input type="checkbox" checked={prefs.homeCards.includes(item.key)} onChange={() => toggleHomeCard(item.key)} /><span>{item.label}</span></label>)}</div>
              <label className="toggle-row settings-toggle-standalone"><input type="checkbox" checked={prefs.showBalances} onChange={e => updateCurrentPrefs({ showBalances: e.target.checked })} /><span>Mostra i saldi delle paghette</span></label>
            </section>

            <section className="settings-subsection">
              <div className="settings-subsection__head"><div><strong>Navigazione mobile</strong><span>Fino a 4 sezioni sempre disponibili</span></div></div>
              <div className="settings-check-grid settings-check-grid--compact">{TAB_OPTIONS.map(item => <label key={item.key} className={prefs.bottomTabs.includes(item.key) ? 'is-selected' : ''}><input type="checkbox" checked={prefs.bottomTabs.includes(item.key)} onChange={() => toggleBottomTab(item.key)} /><span>{item.label}</span></label>)}</div>
              <div className="sortable-list sortable-list--compact">{prefs.bottomTabs.map((key, index) => <div key={key}><span>{TAB_OPTIONS.find(x => x.key === key)?.label || key}</span><div><button disabled={index === 0} onClick={() => moveTab(index, -1)}>↑</button><button disabled={index === prefs.bottomTabs.length - 1} onClick={() => moveTab(index, 1)}>↓</button></div></div>)}</div>
            </section>

            <section className="settings-subsection settings-subsection--wide">
              <div className="settings-subsection__head"><div><strong>Avvisi</strong><span>Scegli quali cambiamenti devono attirare la tua attenzione</span></div></div>
              <div className="settings-toggle-list settings-toggle-list--grid">
                {[
                  ['calendar', 'Calendario', 'Impegni e variazioni'],
                  ['deadlines', 'Scadenze', 'Promemoria prima della data'],
                  ['chores', 'Compiti', 'Nuovi compiti e completamenti'],
                  ['school', 'Scuola', 'Compiti, verifiche e materiale'],
                  ['board', 'Bacheca', 'Nuovi messaggi e promemoria familiari'],
                  ['shopping', 'Lista spesa', 'Aggiornamenti alla lista'],
                  ['whatsapp', 'WhatsApp', 'Canale preferito quando disponibile']
                ].map(([key, label, sub]) => <label key={key}><div><strong>{label}</strong><span>{sub}</span></div><input type="checkbox" checked={(prefs.notifications as any)[key]} onChange={e => updateCurrentPrefs({ notifications: { ...prefs.notifications, [key]: e.target.checked } })} /></label>)}
              </div>
            </section>
          </div>
        </Card>
      </section>

      <section className="settings-section">
        <div className="settings-section__head">
          <div><span>03</span><h2>Connessioni & automazioni</h2></div>
          <p>Servizi esterni che lavorano con VerdoFamily: calendario, report e notifiche automatiche.</p>
        </div>
      <Card className="settings-card--wide">
        <CardHeader title="Google Calendar" subtitle="Ogni adulto può collegare il proprio account e scegliere dove ricevere gli eventi VerdoFamily." />
        {!cloudAuthenticated || !familyId ? <div className="callout">Accedi con il tuo account VerdoFamily cloud per collegare Google Calendar.</div> : !googleStatus ? <div className="backup-actions"><Button variant="soft" icon={<RefreshCw size={17} />} onClick={refreshGoogleCalendar} disabled={googleBusy}>{googleBusy ? 'Controllo…' : 'Verifica configurazione'}</Button></div> : !googleStatus.configured ? <>
          <div className="callout"><strong>Integrazione pronta, manca l’autorizzazione Google.</strong><br />Il backend VerdoFamily è già predisposto. Completa una sola volta la configurazione OAuth indicata da ChatGPT, poi ogni utente potrà collegare il proprio account.</div>
          {googleStatus.redirectUri ? <Field label="URI di reindirizzamento Google" hint="Va inserito tra gli URI autorizzati del client OAuth Google."><input readOnly value={googleStatus.redirectUri} /></Field> : null}
        </> : !googleStatus.connected ? <>
          <div className="callout">Collega il tuo account Google. VerdoFamily richiederà accesso agli eventi e all’elenco dei calendari, senza usare inviti automatici ai familiari.</div>
          <Button icon={<Link2 size={17} />} onClick={connectGoogleCalendar} disabled={googleBusy}>{googleBusy ? 'Collegamento…' : 'Collega Google Calendar'}</Button>
        </> : <>
          <div className="callout callout--success"><strong>✅ Google Calendar collegato</strong>{googleStatus.connection?.googleEmail ? <><br />{googleStatus.connection.googleEmail}</> : null}</div>
          <div className="form-grid form-grid--2">
            <Field label="Calendario personale" hint="Visite e impegni assegnati a te vengono copiati qui."><select value={googleDraft.personalCalendarId} onChange={e => setGoogleDraft({ ...googleDraft, personalCalendarId: e.target.value })}><option value="primary">Calendario principale Google</option>{googleCalendars.filter(item => !item.primary).map(item => <option key={item.id} value={item.id}>{item.summary}</option>)}</select></Field>
            <Field label="Calendario famiglia condiviso" hint="Opzionale: usato dagli eventi marcati Famiglia."><select value={googleDraft.familyCalendarId} onChange={e => setGoogleDraft({ ...googleDraft, familyCalendarId: e.target.value })}><option value="">Nessuno</option>{googleCalendars.map(item => <option key={item.id} value={item.id}>{item.summary}{item.primary ? ' (principale)' : ''}</option>)}</select></Field>
            <Field label="Eventi Famiglia" className="field--wide"><Segmented value={googleDraft.familyEventTarget} onChange={(familyEventTarget: any) => setGoogleDraft({ ...googleDraft, familyEventTarget })} options={[{ value: 'personal', label: 'Calendari personali' }, { value: 'shared', label: 'Solo condiviso' }, { value: 'both', label: 'Entrambi' }]} /></Field>
          </div>
          <div className="callout"><CalendarDays size={16} /> Gli eventi assegnati a più persone vengono copiati nel calendario personale di ciascun partecipante che ha collegato Google. Gli eventi “Famiglia” seguono invece la scelta qui sopra. Non vengono inviati inviti Google.</div>
          <div className="backup-actions"><Button onClick={saveGoogleCalendarSettings} disabled={googleBusy}>Salva e sincronizza</Button><Button variant="soft" icon={<RefreshCw size={17} />} onClick={syncGoogleCalendarNow} disabled={googleBusy}>Sincronizza ora</Button><Button variant="ghost" icon={<Unlink size={17} />} onClick={disconnectGoogleCalendar} disabled={googleBusy}>Scollega</Button></div>
        </>}
        {googleMessage ? <div className="callout" style={{ marginTop: 12 }}>{googleMessage}</div> : null}
      </Card>

      <TelegramReportsCard />
      </section>

      <section className="settings-section">
        <div className="settings-section__head">
          <div><span>04</span><h2>Dati & recupero</h2></div>
          <p>Backup, cronologia e strumenti di emergenza raccolti in un unico punto.</p>
        </div>

      <Card className="settings-card--wide">
        <CardHeader title="Dati & backup" subtitle="Backup automatici nel cloud e su Google Drive, più esportazione manuale locale." />

        {cloudAuthenticated && familyId ? <>
          <div className={backupHealth.ok ? 'callout callout--success' : 'callout'}>
            <strong>{backupHealth.title}</strong><br />
            {backupHealth.detail}
            {driveStatus?.enabled ? <><br />Controllo automatico attivo ogni 5 minuti.</> : null}
          </div>
          <div className="backup-actions">
            <Button variant="soft" icon={<Cloud size={17} />} onClick={runDriveBackup} disabled={backupBusy}>{backupBusy ? 'Backup in corso…' : 'Backup Google Drive ora'}</Button>
            <Button variant="ghost" icon={<RefreshCw size={17} />} onClick={refreshBackupStatus} disabled={backupLoading}>{backupLoading ? 'Verifica…' : 'Verifica stato'}</Button>
          </div>
          <div className="callout">Il backup automatico viene eseguito ogni notte. Se per più di 24 ore non viene registrato un backup riuscito, qui comparirà automaticamente un avviso. Ogni salvataggio importante conserva inoltre una versione precedente nel database.</div>

          {backupHistory.length ? <>
            <CardHeader title="Cronologia ripristinabile" subtitle="Ultime versioni conservate su Supabase" />
            <div className="sortable-list">{backupHistory.map(item => <div key={item.id}><span><strong>Rev. {item.revision}</strong> · {backupReason(item.reason)} · {formatDateTime(item.created_at)}</span><div><button disabled={backupBusy} onClick={() => restoreBackup(item)}>Ripristina</button></div></div>)}</div>
          </> : null}
        </> : <div className="callout">Accedi con il tuo account cloud per attivare backup automatici e cronologia ripristinabile.</div>}

        <CardHeader title="Copia manuale" subtitle="Una copia JSON resta utile anche fuori dal cloud." />
        <div className="backup-actions"><Button variant="soft" icon={<ClipboardCopy size={17} />} onClick={copyBackup}>Copia backup</Button><Button variant="soft" icon={<Download size={17} />} onClick={downloadBackup}>Scarica JSON</Button></div>
        <Field label="Importa backup" hint="Incolla qui un backup JSON creato da VerdoFamily."><textarea rows={5} value={importText} onChange={e => setImportText(e.target.value)} /></Field>
        <div className="backup-footer"><Button variant="ghost" icon={<Upload size={17} />} onClick={doImport}>Importa</Button><Button variant="danger" icon={<RotateCcw size={17} />} onClick={() => { if (confirm('Ripristinare i dati demo? Questa operazione cancella i dati locali.')) resetData() }}>Ripristina dati demo</Button></div>
        {message ? <div className="callout callout--success">{message}</div> : null}
      </Card>
      </section>
    </div>
  </div>
}

import React, { useEffect, useMemo, useState } from 'react'
import { AlertTriangle, Camera, Check, ChevronRight, PackageOpen, Plus, Refrigerator, ScanLine, Search, ShoppingBasket, Snowflake, Sparkles, Trash2, Upload } from 'lucide-react'
import { useFamily } from '../store'
import { Badge, Button, Card, CardHeader, EmptyState, Field, IconButton, Modal, PageIntro, Segmented } from '../ui'
import { localDateISO, normalize, pantryAverageDailyUse, pantryDaysRemaining, pantryExpiryDays, pantryNeedsRestock, parseReceiptLines, similarity } from '../utils'
import type { PantryLocation } from '../types'
import { supabase } from '../supabaseClient'

export default function ShoppingPantryPage() {
  const {
    data,
    addShoppingItem,
    toggleShoppingItem,
    deleteShoppingItem,
    moveTakenShoppingToPantry,
    upsertPantryItem,
    deletePantryItem,
    changePantryQty,
    addCategory,
    renameCategory,
    deleteCategory,
    importReceiptItems,
    cloudAuthenticated,
    familyId
  } = useFamily()

  const [tab, setTab] = useState<'shopping' | 'pantry' | 'insights' | 'scan'>('shopping')
  const [shopName, setShopName] = useState('')
  const [shopQty, setShopQty] = useState(1)
  const [shopUnit, setShopUnit] = useState('pz')
  const [query, setQuery] = useState('')
  const [categoryFilter, setCategoryFilter] = useState('Tutte')
  const [locationFilter, setLocationFilter] = useState<'all' | PantryLocation>('all')
  const [inventoryDestination, setInventoryDestination] = useState<PantryLocation>('pantry')
  const [editingPantry, setEditingPantry] = useState<any>(null)
  const [categoryModal, setCategoryModal] = useState(false)
  const [newCategory, setNewCategory] = useState('')
  const [renaming, setRenaming] = useState<any>(null)

  const [ocrBusy, setOcrBusy] = useState(false)
  const [ocrProgress, setOcrProgress] = useState(0)
  const [ocrError, setOcrError] = useState('')
  const [receiptText, setReceiptText] = useState('')
  const [receiptRows, setReceiptRows] = useState<any[]>([])
  const [removeFromShopping, setRemoveFromShopping] = useState(true)

  const [scanMode, setScanMode] = useState<'receipt' | 'pantry-photo'>('receipt')
  const [visionStatus, setVisionStatus] = useState<{ configured: boolean; model?: string | null } | null>(null)
  const [photoBusy, setPhotoBusy] = useState(false)
  const [photoError, setPhotoError] = useState('')
  const [photoPreview, setPhotoPreview] = useState('')
  const [photoPayload, setPhotoPayload] = useState<{ imageData: string; mimeType: string } | null>(null)
  const [photoRows, setPhotoRows] = useState<any[]>([])

  useEffect(() => {
    if (scanMode !== 'pantry-photo' || !cloudAuthenticated || !familyId || !supabase) return
    void refreshVisionStatus()
  }, [scanMode, cloudAuthenticated, familyId])

  async function callPantryVision(action: string, extra: Record<string, any> = {}) {
    if (!supabase || !familyId) throw new Error('Cloud non disponibile.')
    const { data: result, error } = await supabase.functions.invoke('pantry-photo-recognition', { body: { action, familyId, ...extra } })
    if (error) {
      let detail = ''
      try {
        const payload = await (error as any)?.context?.json?.()
        detail = String(payload?.error || payload?.message || '')
      } catch {}
      throw new Error(detail || error.message || 'Riconoscimento fotografico non disponibile.')
    }
    if (result?.error) throw new Error(result.error)
    return result
  }

  async function refreshVisionStatus() {
    try {
      const result = await callPantryVision('status')
      setVisionStatus({ configured: !!result?.configured, model: result?.model || null })
    } catch {
      setVisionStatus({ configured: false })
    }
  }

  function readFileAsDataUrl(file: File) {
    return new Promise<string>((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = () => resolve(String(reader.result || ''))
      reader.onerror = () => reject(new Error('Impossibile leggere la foto.'))
      reader.readAsDataURL(file)
    })
  }

  async function preparePantryPhoto(file: File) {
    if (!file.type.startsWith('image/')) throw new Error('Seleziona una foto valida.')
    const original = await readFileAsDataUrl(file)
    const supportedRaw = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/heic', 'image/heif'].includes(file.type.toLowerCase())

    // Keep small files untouched; for normal phone photos resize to reduce latency/data usage.
    if (file.size <= 2_800_000 && supportedRaw) {
      return { preview: original, imageData: original.split(',')[1] || '', mimeType: file.type.toLowerCase() }
    }

    try {
      const image = await new Promise<HTMLImageElement>((resolve, reject) => {
        const img = new Image()
        img.onload = () => resolve(img)
        img.onerror = () => reject(new Error('decode'))
        img.src = original
      })
      const maxSide = 1600
      const scale = Math.min(1, maxSide / Math.max(image.naturalWidth || image.width, image.naturalHeight || image.height))
      const width = Math.max(1, Math.round((image.naturalWidth || image.width) * scale))
      const height = Math.max(1, Math.round((image.naturalHeight || image.height) * scale))
      const canvas = document.createElement('canvas')
      canvas.width = width
      canvas.height = height
      const ctx = canvas.getContext('2d')
      if (!ctx) throw new Error('canvas')
      ctx.drawImage(image, 0, 0, width, height)
      const compressed = canvas.toDataURL('image/jpeg', .82)
      return { preview: compressed, imageData: compressed.split(',')[1] || '', mimeType: 'image/jpeg' }
    } catch {
      if (!supportedRaw || file.size > 8_500_000) throw new Error('La foto è troppo grande o in un formato non supportato. Prova con JPG/PNG oppure riduci la dimensione.')
      return { preview: original, imageData: original.split(',')[1] || '', mimeType: file.type.toLowerCase() }
    }
  }

  async function selectPantryPhoto(file: File) {
    setPhotoError('')
    setPhotoRows([])
    try {
      const prepared = await preparePantryPhoto(file)
      setPhotoPreview(prepared.preview)
      setPhotoPayload({ imageData: prepared.imageData, mimeType: prepared.mimeType })
    } catch (error: any) {
      setPhotoPreview('')
      setPhotoPayload(null)
      setPhotoError(error?.message || 'Non riesco a preparare questa foto.')
    }
  }

  function clearPantryPhoto() {
    setPhotoBusy(false)
    setPhotoError('')
    setPhotoRows([])
    setPhotoPreview('')
    setPhotoPayload(null)
  }

  async function analyzePantryPhoto() {
    if (!photoPayload) return
    setPhotoBusy(true)
    setPhotoError('')
    try {
      const result = await callPantryVision('analyze', { ...photoPayload, locationHint: inventoryDestination })
      const catalog = catalogNames()
      const rows = (result?.items || []).map((item: any, index: number) => {
        const exact = item.matchName && catalog.some(name => normalize(name) === normalize(item.matchName))
          ? catalog.find(name => normalize(name) === normalize(item.matchName))
          : ''
        const searchText = `${item.detectedName || ''} ${item.observedText || ''}`.trim()
        const suggestions = catalog
          .map(name => ({ name, score: similarity(searchText, name) }))
          .filter(x => x.score >= .16)
          .sort((a, b) => b.score - a.score)
          .slice(0, 5)
        const top = suggestions[0]
        const confidentExisting = !!exact || (!!top && top.score >= .78)
        const chosenName = exact || (confidentExisting ? top.name : String(item.detectedName || '').trim())
        const category = data.categories.includes(item.category) ? item.category : 'Generico'
        return {
          id: `photo-${Date.now()}-${index}`,
          raw: String(item.detectedName || '').trim(),
          observedText: String(item.observedText || '').trim(),
          notes: String(item.notes || '').trim(),
          confidence: Math.max(0, Math.min(1, Number(item.confidence) || 0)),
          include: true,
          mode: confidentExisting ? 'existing' : 'new',
          name: chosenName,
          qty: Math.max(1, Number(item.qty) || 1),
          unit: item.unit || 'pz',
          category,
          expiryDate: String(item.expiryDate || ''),
          suggestions
        }
      }).filter((row: any) => row.raw)
      setPhotoRows(rows)
      if (!rows.length) setPhotoError('Non ho riconosciuto prodotti con sufficiente affidabilità. Prova una foto più vicina e ben illuminata.')
    } catch (error: any) {
      const raw = error?.message || 'errore sconosciuto'
      setPhotoError(raw.includes('vision_not_configured') ? 'Il riconoscimento fotografico deve ancora essere attivato nelle impostazioni cloud.' : `Analisi non riuscita: ${raw}`)
    } finally {
      setPhotoBusy(false)
    }
  }

  function importPhotoRecognition() {
    const selected = photoRows.filter(x => x.include && x.name.trim()).map(x => ({
      name: x.name.trim(),
      qty: Math.max(1, Number(x.qty) || 1),
      unit: x.unit || 'pz',
      category: x.category || 'Generico',
      location: inventoryDestination,
      expiryDate: x.expiryDate || undefined
    }))
    if (!selected.length) return
    importReceiptItems(selected, removeFromShopping, inventoryDestination)
    setPhotoRows([])
    setPhotoPreview('')
    setPhotoPayload(null)
    setTab('pantry')
  }

  const pending = data.shopping.filter(x => !x.taken)
  const taken = data.shopping.filter(x => x.taken)

  const pantryFiltered = useMemo(() => {
    const q = normalize(query)
    return data.pantry.filter(item => {
      if (categoryFilter !== 'Tutte' && item.category !== categoryFilter) return false
      if (locationFilter !== 'all' && (item.location || 'pantry') !== locationFilter) return false
      if (q && !normalize(item.name).includes(q)) return false
      return true
    }).sort((a, b) => `${a.location || 'pantry'}${a.category}${a.name}`.localeCompare(`${b.location || 'pantry'}${b.category}${b.name}`))
  }, [data.pantry, query, categoryFilter, locationFilter])

  const inventoryStatus = useMemo(() => data.pantry.map(item => {
    const averageDailyUse = pantryAverageDailyUse(item.id, data.pantryMovements)
    const daysRemaining = pantryDaysRemaining(item, data.pantryMovements)
    const expiryDays = pantryExpiryDays(item)
    const needsRestock = pantryNeedsRestock(item, data.pantryMovements)
    return { item, averageDailyUse, daysRemaining, expiryDays, needsRestock }
  }), [data.pantry, data.pantryMovements])

  const restockSuggestions = inventoryStatus
    .filter(entry => entry.needsRestock)
    .sort((a, b) => (a.daysRemaining ?? 9999) - (b.daysRemaining ?? 9999))

  const expiringSoon = inventoryStatus
    .filter(entry => entry.expiryDays !== null && entry.expiryDays <= 7)
    .sort((a, b) => Number(a.expiryDays) - Number(b.expiryDays))

  const locations = {
    pantry: data.pantry.filter(item => (item.location || 'pantry') === 'pantry').length,
    fridge: data.pantry.filter(item => item.location === 'fridge').length,
    freezer: data.pantry.filter(item => item.location === 'freezer').length
  }

  function addQuickShopping() {
    const name = shopName.trim()
    if (!name) return
    addShoppingItem({ name, qty: Math.max(0, Number(shopQty) || 1), unit: shopUnit || 'pz' })
    setShopName('')
    setShopQty(1)
  }

  function openNewPantry() {
    setEditingPantry({ id: undefined, name: '', qty: 1, unit: 'pz', category: data.categories[0] || 'Generico', minQty: 0, location: locationFilter === 'all' ? 'pantry' : locationFilter, expiryDate: '', autoRestock: true })
  }

  function savePantry() {
    if (!editingPantry?.name?.trim()) return
    upsertPantryItem({ ...editingPantry, name: editingPantry.name.trim(), qty: Number(editingPantry.qty) || 0, minQty: Number(editingPantry.minQty) || 0, location: editingPantry.location || 'pantry', expiryDate: editingPantry.expiryDate || undefined, autoRestock: editingPantry.autoRestock !== false })
    setEditingPantry(null)
  }

  function locationLabel(location?: PantryLocation) {
    if (location === 'fridge') return 'Frigo'
    if (location === 'freezer') return 'Freezer'
    return 'Dispensa'
  }

  function suggestedBuyQty(item: any, daysRemaining: number | null) {
    const minGap = Math.max(0, Number(item.minQty || 0) - Number(item.qty || 0))
    const average = pantryAverageDailyUse(item.id, data.pantryMovements)
    const weekGap = average > 0 ? Math.max(0, Math.ceil((average * 7) - Number(item.qty || 0))) : 0
    return Math.max(1, minGap, weekGap)
  }

  function addRestockSuggestion(item: any, daysRemaining: number | null) {
    const exists = data.shopping.some(row => !row.taken && normalize(row.name) === normalize(item.name))
    if (exists) return
    addShoppingItem({
      name: item.name,
      qty: suggestedBuyQty(item, daysRemaining),
      unit: item.unit || 'pz',
      category: item.category || 'Generico'
    })
  }

  function looksLikeReceiptText(text: string) {
    const clean = text.replace(/\s+/g, ' ').toUpperCase()
    const priceHits = (clean.match(/\b\d{1,4}[,.]\d{2}\b/g) || []).length
    const receiptTerms = ['TOTALE', 'SUBTOTALE', 'IMPORTO', 'SCONTRINO', 'RESTO', 'CASSA', 'P.IVA', 'IVA ', 'Q.TA', 'QTA', 'EURO']
    const keywordHits = receiptTerms.reduce((sum, term) => sum + (clean.includes(term) ? 1 : 0), 0)
    const usefulLines = text.split(/\r?\n/).map(line => line.trim()).filter(line => line.length >= 3).length
    return priceHits >= 3 || keywordHits >= 2 || (keywordHits >= 1 && priceHits >= 1 && usefulLines >= 5)
  }

  async function runOcr(file: File) {
    setOcrBusy(true)
    setOcrProgress(0)
    setOcrError('')
    try {
      const mod: any = await import('tesseract.js')
      const T = mod.default || mod
      const res = await T.recognize(file, 'ita', {
        logger: (msg: any) => {
          if (msg?.status === 'recognizing text' && typeof msg.progress === 'number') setOcrProgress(msg.progress)
        }
      })
      const text = res?.data?.text || ''
      if (!text.trim()) throw new Error('empty')

      // Product/scenery photos can produce pages of meaningless OCR. Never expose
      // that dump to the user: move the same photo to visual product recognition.
      if (!looksLikeReceiptText(text)) {
        setReceiptText('')
        setReceiptRows([])
        setScanMode('pantry-photo')
        await selectPantryPhoto(file)
        setPhotoError('Questa immagine non sembra uno scontrino. L’ho preparata per il riconoscimento dei prodotti: premi “Riconosci prodotti”.')
        return
      }

      setReceiptText(text)
      analyzeReceipt(text)
    } catch {
      setOcrError('Non sono riuscito a leggere bene lo scontrino. Prova una foto più nitida oppure usa “Foto dispensa” per riconoscere direttamente i prodotti.')
    } finally {
      setOcrBusy(false)
    }
  }

  function catalogNames() {
    const names = new Map<string, string>()
    data.pantry.forEach(x => names.set(normalize(x.name), x.name))
    data.shopping.forEach(x => names.set(normalize(x.name), x.name))
    data.dishes.forEach(d => d.ingredients.forEach(x => names.set(normalize(x.name), x.name)))
    return [...names.values()]
  }

  function analyzeReceipt(text = receiptText) {
    const lines = parseReceiptLines(text)
    const catalog = catalogNames()
    const rows = lines.map((raw, index) => {
      const suggestions = catalog
        .map(name => ({ name, score: similarity(raw, name) }))
        .filter(x => x.score >= 0.18)
        .sort((a, b) => b.score - a.score)
        .slice(0, 5)
      const top = suggestions[0]
      const confident = !!top && top.score >= 0.72
      return {
        id: `${Date.now()}-${index}`,
        raw,
        include: true,
        mode: confident ? 'existing' : 'new',
        name: confident ? top.name : raw,
        qty: 1,
        unit: 'pz',
        category: 'Generico',
        suggestions
      }
    })
    setReceiptRows(rows)
  }

