            <Segmented value={inventoryDestination} onChange={setInventoryDestination} options={[{ value: 'pantry', label: 'Dispensa' }, { value: 'fridge', label: 'Frigo' }, { value: 'freezer', label: 'Freezer' }]} />
          </div>

          {scanMode === 'receipt' ? <div className="scan-layout">
          <Card>
            <CardHeader title="1. Leggi lo scontrino" subtitle="Fotocamera su iPhone/Android oppure testo incollato." />
            <div className="image-source-grid">
              <label className="image-source-option">
                <input type="file" accept="image/*" capture="environment" onChange={e => { const file = e.target.files?.[0]; if (file) runOcr(file); e.currentTarget.value = '' }} />
                <Camera size={28} />
                <strong>Scatta foto</strong>
                <span>Apri direttamente la fotocamera.</span>
              </label>
              <label className="image-source-option">
                <input type="file" accept="image/*" onChange={e => { const file = e.target.files?.[0]; if (file) runOcr(file); e.currentTarget.value = '' }} />
                <Upload size={28} />
                <strong>Scegli foto esistente</strong>
                <span>Apri galleria, Foto o File del dispositivo.</span>
              </label>
            </div>
            <div className="image-source-hint">Meglio se la foto è dritta, nitida e ben illuminata.</div>
            {ocrBusy ? <div className="progress-row"><div className="progress-track"><span style={{ width: `${Math.round(ocrProgress * 100)}%` }} /></div><strong>{Math.round(ocrProgress * 100)}%</strong></div> : null}
            {ocrError ? <div className="callout callout--warning">{ocrError}</div> : null}
            <Field label="Testo riconosciuto" hint="Puoi correggerlo prima dell'analisi.">
              <textarea rows={8} value={receiptText} onChange={e => setReceiptText(e.target.value)} placeholder="Incolla qui il testo dello scontrino…" />
            </Field>
            <Button icon={<ScanLine size={18} />} disabled={!receiptText.trim()} onClick={() => analyzeReceipt()}>Analizza prodotti</Button>
          </Card>

          <Card>
            <CardHeader title="2. Verifica associazioni" subtitle="Quando il match non è sicuro, scegli un prodotto esistente oppure creane uno nuovo." />
            {receiptRows.length ? (
              <div className="receipt-matches">
                {receiptRows.map(row => (
                  <div key={row.id} className="receipt-match">
                    <div className="receipt-match__head">
                      <label><input type="checkbox" checked={row.include} onChange={e => setReceiptRows(prev => prev.map(x => x.id === row.id ? { ...x, include: e.target.checked } : x))} /><span>{row.raw}</span></label>
                      {row.mode === 'existing' ? <Badge tone="success">Associato</Badge> : <Badge tone="warning">Da verificare</Badge>}
                    </div>
                    {row.include ? (
                      <div className="receipt-match__grid">
                        <Field label="Associazione">
                          <select value={row.mode} onChange={e => setReceiptRows(prev => prev.map(x => x.id === row.id ? { ...x, mode: e.target.value } : x))}>
                            <option value="existing">Prodotto esistente</option>
                            <option value="new">Crea nuovo prodotto</option>
                          </select>
                        </Field>
                        {row.mode === 'existing' ? (
                          <Field label="Prodotto">
                            <select value={row.name} onChange={e => setReceiptRows(prev => prev.map(x => x.id === row.id ? { ...x, name: e.target.value } : x))}>
                              {row.suggestions.length ? row.suggestions.map((s: any) => <option key={s.name} value={s.name}>{s.name} · {Math.round(s.score * 100)}%</option>) : <option value={row.name}>{row.name}</option>}
                              {catalogNames().filter(n => !row.suggestions.some((s: any) => s.name === n)).map(name => <option key={name} value={name}>{name}</option>)}
                            </select>
                          </Field>
                        ) : (
                          <Field label="Nome nuovo prodotto"><input value={row.name} onChange={e => setReceiptRows(prev => prev.map(x => x.id === row.id ? { ...x, name: e.target.value } : x))} /></Field>
                        )}
                        <Field label="Quantità"><input type="number" min="0" value={row.qty} onChange={e => setReceiptRows(prev => prev.map(x => x.id === row.id ? { ...x, qty: Number(e.target.value) } : x))} /></Field>
                        <Field label="Unità"><select value={row.unit} onChange={e => setReceiptRows(prev => prev.map(x => x.id === row.id ? { ...x, unit: e.target.value } : x))}><option value="pz">pz</option><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">l</option></select></Field>
                        {row.mode === 'new' ? <Field label="Categoria"><select value={row.category} onChange={e => setReceiptRows(prev => prev.map(x => x.id === row.id ? { ...x, category: e.target.value } : x))}>{data.categories.map(cat => <option key={cat}>{cat}</option>)}</select></Field> : null}
                      </div>
                    ) : null}
                  </div>
                ))}
                <label className="toggle-row"><input type="checkbox" checked={removeFromShopping} onChange={e => setRemoveFromShopping(e.target.checked)} /><span>Se il prodotto era nella lista spesa, rimuovilo automaticamente</span></label>
                <Button icon={<PackageOpen size={18} />} onClick={importReceipt}>Importa in dispensa</Button>
              </div>
            ) : (
              <EmptyState icon={<ScanLine size={30} />} title="In attesa dello scontrino" text="Dopo l'analisi compariranno qui i prodotti da confermare." />
            )}
          </Card>
        </div> : null}

          {scanMode === 'pantry-photo' ? <div className="scan-layout pantry-photo-scan">
            <Card>
              <CardHeader title="1. Fotografa la dispensa" subtitle="Puoi fotografare uno scaffale, il frigorifero o un gruppo di prodotti." />
              {!cloudAuthenticated || !familyId ? <div className="callout">Accedi al cloud VerdoFamily per usare il riconoscimento fotografico.</div> : visionStatus && !visionStatus.configured ? <div className="callout callout--warning"><strong>Riconoscimento AI da attivare</strong><br />Il modulo è installato, ma manca la chiave Gemini nel backend.</div> : null}
              {photoPreview ? <div className="pantry-photo-preview"><img src={photoPreview} alt="Foto dispensa da analizzare" /><div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}><span>Foto pronta per il riconoscimento</span><Button variant="danger" size="sm" icon={<Trash2 size={16} />} onClick={clearPantryPhoto}>Rimuovi foto</Button></div></div> : null}
              <div className="image-source-grid image-source-grid--pantry">
                <label className="image-source-option">
                  <input type="file" accept="image/*" capture="environment" onChange={e => { const file = e.target.files?.[0]; if (file) void selectPantryPhoto(file); e.currentTarget.value = '' }} />
                  <Camera size={30} />
                  <strong>{photoPreview ? 'Scatta un’altra foto' : 'Scatta foto'}</strong>
                  <span>Usa la fotocamera del tablet o telefono.</span>
                </label>
                <label className="image-source-option">
                  <input type="file" accept="image/*" onChange={e => { const file = e.target.files?.[0]; if (file) void selectPantryPhoto(file); e.currentTarget.value = '' }} />
                  <Upload size={30} />
                  <strong>{photoPreview ? 'Scegli un’altra foto' : 'Scegli foto esistente'}</strong>
                  <span>Apri galleria, Foto o File del dispositivo.</span>
                </label>
              </div>
              <div className="image-source-hint">Per risultati migliori: foto frontale, luce uniforme e prodotti non troppo sovrapposti.</div>
              <div className="callout">🔒 La foto viene usata solo per il riconoscimento e non viene salvata nella dispensa o negli allegati.</div>
              {photoError ? <div className="callout callout--warning">{photoError}</div> : null}
              <Button icon={<ScanLine size={18} />} disabled={!photoPayload || photoBusy || visionStatus?.configured === false} onClick={analyzePantryPhoto}>{photoBusy ? 'Riconoscimento in corso…' : 'Riconosci prodotti'}</Button>
            </Card>

            <Card>
              <CardHeader title="2. Controlla e carica" subtitle="Nessuna quantità viene modificata senza la tua conferma." />
              {photoBusy ? <div className="vision-loading"><ScanLine size={28} /><strong>Sto guardando la foto…</strong><span>Leggo confezioni, etichette e quantità visibili.</span></div> : photoRows.length ? <div className="receipt-matches">
                <div className="vision-summary"><strong>{photoRows.length} {photoRows.length === 1 ? 'prodotto riconosciuto' : 'prodotti riconosciuti'}</strong><span>Controlla soprattutto le righe con confidenza più bassa.</span></div>
                {photoRows.map(row => <div key={row.id} className="receipt-match">
                  <div className="receipt-match__head">
                    <label><input type="checkbox" checked={row.include} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, include: e.target.checked } : x))} /><span>{row.raw}{row.observedText ? <small> · letto: {row.observedText}</small> : null}</span></label>
                    <Badge tone={row.confidence >= .8 ? 'success' : row.confidence >= .55 ? 'warning' : 'danger'}>{Math.round(row.confidence * 100)}%</Badge>
                  </div>
                  {row.include ? <div className="receipt-match__grid">
                    <Field label="Associazione"><select value={row.mode} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, mode: e.target.value } : x))}><option value="existing">Prodotto esistente</option><option value="new">Crea nuovo prodotto</option></select></Field>
                    {row.mode === 'existing' ? <Field label="Prodotto"><select value={row.name} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, name: e.target.value } : x))}>{row.suggestions.length ? row.suggestions.map((suggestion: any) => <option key={suggestion.name} value={suggestion.name}>{suggestion.name} · {Math.round(suggestion.score * 100)}%</option>) : <option value={row.name}>{row.name}</option>}{catalogNames().filter(name => !row.suggestions.some((suggestion: any) => suggestion.name === name)).map(name => <option key={name} value={name}>{name}</option>)}</select></Field> : <Field label="Nome prodotto"><input value={row.name} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, name: e.target.value } : x))} /></Field>}
                    <Field label="Quantità"><input type="number" min="1" value={row.qty} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, qty: Number(e.target.value) } : x))} /></Field>
                    <Field label="Unità"><select value={row.unit} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, unit: e.target.value } : x))}><option value="pz">pz</option><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">l</option></select></Field>
                    {row.mode === 'new' ? <Field label="Categoria"><select value={row.category} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, category: e.target.value } : x))}>{data.categories.map(cat => <option key={cat}>{cat}</option>)}</select></Field> : null}
                    <Field label="Scadenza" hint="Solo se visibile/certa"><input type="date" value={row.expiryDate || ''} onChange={e => setPhotoRows(prev => prev.map(x => x.id === row.id ? { ...x, expiryDate: e.target.value } : x))} /></Field>
                  </div> : null}
                </div>)}
                <label className="toggle-row"><input type="checkbox" checked={removeFromShopping} onChange={e => setRemoveFromShopping(e.target.checked)} /><span>Se un prodotto era nella lista spesa, rimuovilo automaticamente</span></label>
                <Button icon={<PackageOpen size={18} />} onClick={importPhotoRecognition}>Conferma e carica in dispensa</Button>
              </div> : <EmptyState icon={<Camera size={30} />} title="In attesa della foto" text="Dopo il riconoscimento vedrai qui i prodotti, le quantità stimate e le associazioni da confermare." />}
            </Card>
          </div> : null}
        </div>
      ) : null}

      <Modal
        open={!!editingPantry}
        onClose={() => setEditingPantry(null)}
        title={editingPantry?.id ? 'Modifica prodotto' : 'Nuovo prodotto in inventario'}
        footer={<div className="modal-actions"><div>{editingPantry?.id ? <Button variant="danger" icon={<Trash2 size={17} />} onClick={() => { deletePantryItem(editingPantry.id); setEditingPantry(null) }}>Elimina</Button> : null}</div><div className="modal-actions__right"><Button variant="ghost" onClick={() => setEditingPantry(null)}>Annulla</Button><Button onClick={savePantry}>Salva</Button></div></div>}
      >
        {editingPantry ? <div className="form-grid form-grid--2">
          <Field label="Prodotto" className="field--wide"><input autoFocus value={editingPantry.name} onChange={e => setEditingPantry({ ...editingPantry, name: e.target.value })} /></Field>
          <Field label="Quantità"><input type="number" min="0" value={editingPantry.qty} onChange={e => setEditingPantry({ ...editingPantry, qty: Number(e.target.value) })} /></Field>
          <Field label="Unità"><select value={editingPantry.unit} onChange={e => setEditingPantry({ ...editingPantry, unit: e.target.value })}><option value="pz">pz</option><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">l</option></select></Field>
          <Field label="Categoria"><select value={editingPantry.category} onChange={e => setEditingPantry({ ...editingPantry, category: e.target.value })}>{data.categories.map(cat => <option key={cat}>{cat}</option>)}</select></Field>
          <Field label="Posizione"><select value={editingPantry.location || 'pantry'} onChange={e => setEditingPantry({ ...editingPantry, location: e.target.value as PantryLocation })}><option value="pantry">Dispensa</option><option value="fridge">Frigo</option><option value="freezer">Freezer</option></select></Field>
          <Field label="Scadenza" hint="Facoltativa"><input type="date" value={editingPantry.expiryDate || ''} onChange={e => setEditingPantry({ ...editingPantry, expiryDate: e.target.value })} /></Field>
          <Field label="Soglia minima" hint="0 = solo previsione consumo"><input type="number" min="0" value={editingPantry.minQty || 0} onChange={e => setEditingPantry({ ...editingPantry, minQty: Number(e.target.value) })} /></Field>
          <label className="toggle-row field--wide"><input type="checkbox" checked={editingPantry.autoRestock !== false} onChange={e => setEditingPantry({ ...editingPantry, autoRestock: e.target.checked })} /><span><strong>Suggerimenti automatici di riacquisto</strong><small>Usa soglia minima e consumo medio per avvisarti prima che finisca.</small></span></label>
        </div> : null}
      </Modal>

      <Modal open={categoryModal} onClose={() => setCategoryModal(false)} title="Categorie dispensa" subtitle="Rinomina o elimina senza perdere i prodotti.">
        <div className="category-editor">
          <div className="quick-input-row quick-input-row--category"><input value={newCategory} onChange={e => setNewCategory(e.target.value)} placeholder="Nuova categoria" /><Button onClick={() => { if (addCategory(newCategory)) setNewCategory('') }}>Aggiungi</Button></div>
          <div className="category-list">
            {data.categories.map(cat => <div key={cat} className="category-row"><span>{cat}</span><div>{cat !== 'Generico' ? <><button onClick={() => setRenaming({ old: cat, value: cat })}>Rinomina</button><button className="danger-link" onClick={() => deleteCategory(cat)}>Elimina</button></> : <Badge>Predefinita</Badge>}</div></div>)}
          </div>
          {renaming ? <div className="rename-box"><Field label={`Rinomina “${renaming.old}”`}><input value={renaming.value} onChange={e => setRenaming({ ...renaming, value: e.target.value })} /></Field><div className="modal-actions__right"><Button variant="ghost" onClick={() => setRenaming(null)}>Annulla</Button><Button onClick={() => { if (renameCategory(renaming.old, renaming.value)) setRenaming(null) }}>Salva</Button></div></div> : null}
        </div>
      </Modal>
    </div>
  )
}

import React, { useMemo, useState } from 'react'
import { CalendarClock, Check, History, Pencil, Plus, Repeat2, RotateCcw, Trash2 } from 'lucide-react'
import { useFamily } from '../store'
import { Avatar, Badge, Button, Card, CardHeader, EmptyState, Field, IconButton, Modal, PageIntro, Segmented } from '../ui'
import { dayLabel, localDateISO, nextRoutineDueDate, routineCompletedOn, routineDueOn } from '../utils'
import type { RoutineFrequency } from '../types'

const FREQUENCIES: Array<{ value: RoutineFrequency; label: string }> = [
  { value: 'daily', label: 'Ogni giorno' },
  { value: 'weekly', label: 'Ogni settimana' },
  { value: 'fortnightly', label: 'Ogni 2 settimane' },
  { value: 'monthly', label: 'Ogni mese' },
  { value: 'semiannual', label: 'Ogni 6 mesi' },
  { value: 'yearly', label: 'Ogni anno' }
]

function frequencyLabel(value: RoutineFrequency) {
  return FREQUENCIES.find(item => item.value === value)?.label || 'Ricorrente'
}

export default function TodosPage() {
  const {
    data,
    authUser,
    addTodo,
    toggleTodo,
    deleteTodo,
    upsertRoutine,
    toggleRoutineActive,
    deleteRoutine,
    completeRoutine,
    undoRoutineCompletion
  } = useFamily()

  const today = localDateISO()
  const isChild = authUser?.role === 'bimbo'
  const [view, setView] = useState<'today' | 'routines' | 'archive'>('today')
  const [title, setTitle] = useState('')
  const [userId, setUserId] = useState(authUser?.id || data.users[0]?.id || 1)
  const [routineEditing, setRoutineEditing] = useState<any>(null)

  const openTodos = useMemo(
    () => data.todos.filter(item => !item.done).sort((a, b) => b.id - a.id),
    [data.todos]
  )

  const dueRoutines = useMemo(
    () => data.routines
      .filter(routine => routineDueOn(routine, today))
      .filter(routine => !isChild || routine.userId === authUser?.id)
      .sort((a, b) => a.userId - b.userId || a.title.localeCompare(b.title)),
    [data.routines, today, isChild, authUser?.id]
  )

  const dueOpenCount = dueRoutines.filter(routine => !routineCompletedOn(data.routineCompletions, routine.id, today)).length
  const visibleRoutines = data.routines
    .filter(routine => !isChild || routine.userId === authUser?.id)
    .slice()
    .sort((a, b) => Number(b.active) - Number(a.active) || a.title.localeCompare(b.title))

  const archiveEntries = useMemo(() => {
    const todoEntries = data.todos
      .filter(item => item.done)
      .map(item => ({
        key: `todo-${item.id}`,
        kind: 'todo' as const,
        title: item.title,
        userId: item.userId,
        date: item.createdAt,
        item
      }))

    const routineEntries = data.routineCompletions
      .filter(item => !isChild || item.userId === authUser?.id)
      .map(item => {
        const routine = data.routines.find(r => r.id === item.routineId)
        return {
          key: `routine-${item.id}`,
          kind: 'routine' as const,
          title: routine?.title || 'Routine eliminata',
          userId: item.userId,
          date: item.date,
          item,
          routine
        }
      })

    return [...todoEntries, ...routineEntries]
      .sort((a, b) => b.date.localeCompare(a.date) || b.key.localeCompare(a.key))
  }, [data.todos, data.routineCompletions, data.routines, isChild, authUser?.id])

  function submit() {
    if (!title.trim()) return
    addTodo({ title: title.trim(), userId: Number(userId) })
    setTitle('')
  }

  function openRoutine(item?: any) {
    if (isChild) return
    setRoutineEditing(item
      ? { ...item }
      : {
          title: '',
          userId: data.users[0]?.id || 1,
          frequency: 'weekly' as RoutineFrequency,
          startDate: today,
          endDate: '',
          active: true,
          notes: ''
        })
  }

  function saveRoutine() {
    if (isChild || !routineEditing?.title?.trim()) return
    upsertRoutine({
      id: routineEditing.id,
      title: routineEditing.title.trim(),
      userId: Number(routineEditing.userId),
      frequency: routineEditing.frequency,
      startDate: routineEditing.startDate || today,
      endDate: routineEditing.endDate || undefined,
      active: routineEditing.active !== false,
      notes: routineEditing.notes || ''
    })
    setRoutineEditing(null)
  }

  const todayTotal = openTodos.length + dueOpenCount
  const tabs = [
    { value: 'today', label: `Oggi · ${todayTotal}` },
    { value: 'routines', label: `Routine · ${visibleRoutines.filter(routine => routine.active).length}` },
    { value: 'archive', label: `Archivio · ${archiveEntries.length}` }
  ]

  return <div className="page">
    <PageIntro
      eyebrow="Organizzazione quotidiana"
      title="Da fare & routine"
      description={isChild
        ? 'Qui trovi i tuoi promemoria e le routine che ti sono state assegnate.'
        : 'Promemoria veloci e attività ricorrenti della famiglia, senza duplicare ogni volta le stesse cose.'}
      actions={!isChild && view === 'routines'
        ? <Button icon={<Repeat2 size={18} />} onClick={() => openRoutine()}>Nuova routine</Button>
        : null}
    />

    <div className="page-tabs-wrap">
      <Segmented value={view} onChange={setView} options={tabs} />
    </div>

    {view === 'today' ? <>
      <Card className="todo-compose-card">
        <div className="todo-compose">
          <input
            autoComplete="off"
            value={title}
            onChange={e => setTitle(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter') submit() }}
            placeholder="Aggiungi un promemoria…"
          />
          <select value={userId} onChange={e => setUserId(Number(e.target.value))}>
            {(isChild && authUser ? [authUser] : data.users).map(user => <option key={user.id} value={user.id}>{user.name}</option>)}
          </select>
          <Button icon={<Plus size={17} />} onClick={submit}>Aggiungi</Button>
        </div>
      </Card>

      <div className="todo-routine-grid">
        <Card>
          <CardHeader
            title="Routine di oggi"
            subtitle={dueOpenCount ? `${dueOpenCount} ancora da completare` : 'Tutto completato'}
          />
          {dueRoutines.length ? <div className="check-list">
            {dueRoutines.map(routine => {
              const done = routineCompletedOn(data.routineCompletions, routine.id, today)
              const user = data.users.find(item => item.id === routine.userId)
              return <div key={routine.id} className={`check-item routine-due-item ${done ? 'is-done' : ''}`}>
                <button
                  className="check-item__check"
                  onClick={() => done ? undoRoutineCompletion(routine.id, today) : completeRoutine(routine.id, today)}
                  title={done ? 'Segna nuovamente da fare' : 'Segna come completata'}
                >
                  {done ? <Check size={16} /> : null}
                </button>
                <button
                  className="check-item__copy"
                  onClick={() => done ? undoRoutineCompletion(routine.id, today) : completeRoutine(routine.id, today)}
                >
                  <strong>{routine.title}</strong>
                  <span><Avatar user={user} size="xs" /> {user?.name} · {frequencyLabel(routine.frequency)}</span>
                  {routine.notes ? <small>{routine.notes}</small> : null}
                </button>
                <Badge tone={done ? 'success' : 'neutral'}>{done ? 'Fatta' : 'Oggi'}</Badge>
              </div>
            })}
          </div> : <EmptyState
            icon={<Repeat2 size={28} />}
            title="Nessuna routine oggi"
            text="Non ci sono attività ricorrenti previste per oggi."
          />}
        </Card>

        <Card>
          <CardHeader title="Promemoria aperti" subtitle={openTodos.length ? `${openTodos.length} da fare` : 'Nessun promemoria'} />
          {openTodos.length ? <div className="check-list">
            {openTodos.map(item => {
              const user = data.users.find(u => u.id === item.userId)
              return <div key={item.id} className="check-item">
                <button className="check-item__check" onClick={() => toggleTodo(item.id)} />
                <button className="check-item__copy" onClick={() => toggleTodo(item.id)}>
                  <strong>{item.title}</strong>
                  <span><Avatar user={user} size="xs" /> {user?.name} · {item.createdAt}</span>
                </button>
                <IconButton label="Elimina" onClick={() => deleteTodo(item.id)}><Trash2 size={17} /></IconButton>
              </div>
            })}
          </div> : <EmptyState title="Tutto fatto" text="Nessun promemoria aperto." />}
        </Card>
      </div>
    </> : null}

    {view === 'routines' ? <Card>
      <CardHeader
        title={isChild ? 'Le mie routine' : 'Routine familiari'}
        subtitle={isChild ? 'Attività ricorrenti assegnate a te' : 'Una sola regola, tutte le ricorrenze calcolate automaticamente'}
      />
      {visibleRoutines.length ? <div className="routine-list">
        {visibleRoutines.map(routine => {
          const user = data.users.find(item => item.id === routine.userId)
          const nextDue = nextRoutineDueDate(routine, today)
          return <div key={routine.id} className={`routine-row ${routine.active ? '' : 'is-disabled'}`}>
            {!isChild ? <label className="recurring-switch" title={routine.active ? 'Metti in pausa' : 'Riattiva'}>
              <input type="checkbox" checked={routine.active} onChange={() => toggleRoutineActive(routine.id)} />
            </label> : <Repeat2 size={17} />}
            <button className="routine-row__copy" onClick={() => !isChild && openRoutine(routine)} disabled={isChild}>
              <strong>{routine.title}</strong>
              <span><Avatar user={user} size="xs" /> {user?.name} · {frequencyLabel(routine.frequency)}</span>
              <small>
                {routine.active
                  ? nextDue ? `Prossima: ${dayLabel(nextDue, true)}` : 'Nessuna prossima ricorrenza'
                  : 'Routine in pausa'}
              </small>
              {routine.notes ? <em>{routine.notes}</em> : null}
            </button>
            <Badge tone={routine.active ? 'success' : 'neutral'}>{routine.active ? 'Attiva' : 'Pausa'}</Badge>
            {!isChild ? <IconButton label="Modifica" onClick={() => openRoutine(routine)}><Pencil size={16} /></IconButton> : null}
            {!isChild ? <IconButton label="Elimina" onClick={() => deleteRoutine(routine.id)}><Trash2 size={16} /></IconButton> : null}
          </div>
        })}
      </div> : <EmptyState
        icon={<CalendarClock size={28} />}
        title="Nessuna routine"
        text={isChild
          ? 'Non hai ancora routine assegnate.'
          : 'Crea attività come pattumiere, cambio lenzuola, filtri, zaini o controlli periodici.'}
        action={!isChild ? <Button variant="soft" onClick={() => openRoutine()}>Crea la prima routine</Button> : null}
      />}
    </Card> : null}

    {view === 'archive' ? <Card>
      <CardHeader title="Storico attività" subtitle="Promemoria completati e singole esecuzioni delle routine" />
      {archiveEntries.length ? <div className="check-list">
        {archiveEntries.slice(0, 150).map(entry => {
          const user = data.users.find(item => item.id === entry.userId)
          return <div key={entry.key} className="check-item is-done">
            <span className="check-item__check"><Check size={16} /></span>
            <div className="check-item__copy routine-history-copy">
              <strong>{entry.title}</strong>
              <span>
                <Avatar user={user} size="xs" /> {user?.name} · {entry.date} · {entry.kind === 'routine' ? 'Routine' : 'Promemoria'}
              </span>
            </div>
            {entry.kind === 'routine' && entry.routine
              ? <IconButton label="Annulla completamento" onClick={() => undoRoutineCompletion(entry.routine!.id, entry.date)}><RotateCcw size={16} /></IconButton>
              : entry.kind === 'todo'
                ? <IconButton label="Riapri" onClick={() => toggleTodo(entry.item.id)}><RotateCcw size={16} /></IconButton>
                : null}
          </div>
        })}
      </div> : <EmptyState icon={<History size={28} />} title="Archivio vuoto" text="Le attività completate appariranno qui." />}
    </Card> : null}

    {!isChild ? <Modal
      open={!!routineEditing}
      onClose={() => setRoutineEditing(null)}
      title={routineEditing?.id ? 'Modifica routine' : 'Nuova routine'}
      subtitle="La data iniziale determina il giorno di riferimento della ricorrenza."
      footer={<div className="modal-actions"><span /><div className="modal-actions__right">
        <Button variant="ghost" onClick={() => setRoutineEditing(null)}>Annulla</Button>
        <Button onClick={saveRoutine}>Salva routine</Button>
      </div></div>}
    >
      {routineEditing ? <div className="form-grid form-grid--2">
        <Field label="Attività" className="field--wide">
          <input
            autoFocus
            value={routineEditing.title}
            onChange={e => setRoutineEditing({ ...routineEditing, title: e.target.value })}
            placeholder="Es. Cambio lenzuola"
          />
        </Field>
        <Field label="Assegna a">
          <select value={routineEditing.userId} onChange={e => setRoutineEditing({ ...routineEditing, userId: Number(e.target.value) })}>
            {data.users.map(user => <option key={user.id} value={user.id}>{user.name}</option>)}
          </select>
        </Field>
        <Field label="Frequenza">
          <select value={routineEditing.frequency} onChange={e => setRoutineEditing({ ...routineEditing, frequency: e.target.value as RoutineFrequency })}>
            {FREQUENCIES.map(item => <option key={item.value} value={item.value}>{item.label}</option>)}
          </select>
        </Field>
        <Field label="Prima esecuzione">
          <input
            type="date"
            value={routineEditing.startDate}
            onChange={e => setRoutineEditing({ ...routineEditing, startDate: e.target.value })}
          />
        </Field>
        <Field label="Fino al" hint="Facoltativo">
          <input
            type="date"
            min={routineEditing.startDate || undefined}
            value={routineEditing.endDate || ''}
            onChange={e => setRoutineEditing({ ...routineEditing, endDate: e.target.value })}
          />
        </Field>
        <Field label="Note" className="field--wide">
          <textarea
            rows={3}
            value={routineEditing.notes || ''}
            onChange={e => setRoutineEditing({ ...routineEditing, notes: e.target.value })}
            placeholder="Es. ricordarsi anche delle federe"
          />
        </Field>
        <label className="toggle-row field--wide">
          <input
            type="checkbox"
            checked={routineEditing.active !== false}
            onChange={e => setRoutineEditing({ ...routineEditing, active: e.target.checked })}
          />
          Attiva
        </label>
      </div> : null}
    </Modal> : null}
  </div>
}

import React, { useState } from 'react'
import { Camera, Cloud, Copy, KeyRound, Plus, ShieldCheck, Trash2, UserPlus, UserRound } from 'lucide-react'
import { useFamily } from '../store'
import { Avatar, Badge, Button, Card, EmptyState, Field, IconButton, Modal, PageIntro, Segmented } from '../ui'
import { DEFAULT_PREFS } from '../utils'

function fileToDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const r = new FileReader()
    r.onload = () => resolve(String(r.result || ''))
    r.onerror = reject
    r.readAsDataURL(file)
  })
}

export default function UsersPage() {
  const { data, authUser, addUser, updateUser, deleteUser, cloudAuthenticated, familyName, createFamilyInvite } = useFamily()
  const isAdmin = authUser?.role === 'admin'
  const [editing, setEditing] = useState<any>(null)
  const [inviteRole, setInviteRole] = useState<'adult' | 'child'>('adult')
  const [inviteCode, setInviteCode] = useState('')
  const [inviteError, setInviteError] = useState('')
  const [inviteBusy, setInviteBusy] = useState(false)
  const [copyLabel, setCopyLabel] = useState('Copia')

  function openNew() {
    if (!isAdmin) return
    setEditing({ id: undefined, name: '', role: 'adulto', password: '', color: '#5B5BD6', avatarUrl: '' })
  }

  async function avatarFromFile(file?: File) {
    if (!file || !editing) return
    const avatarUrl = await fileToDataUrl(file)
    setEditing({ ...editing, avatarUrl })
  }

  function save() {
    if (!editing?.name?.trim()) return
    if (!cloudAuthenticated && !editing?.password) return
    if (editing.id) updateUser(editing.id, { ...editing, name: editing.name.trim() })
    else addUser({ name: editing.name.trim(), role: editing.role, password: editing.password || '', color: editing.color, avatarUrl: editing.avatarUrl, prefs: { ...DEFAULT_PREFS, accent: editing.color } })
    setEditing(null)
  }

  async function generateInvite() {
    setInviteBusy(true)
    setInviteError('')
    setInviteCode('')
    try {
      const result = await createFamilyInvite(inviteRole)
      if (!result.ok) setInviteError(result.error || 'Impossibile creare il codice.')
      else setInviteCode(result.code || '')
    } finally {
      setInviteBusy(false)
    }
  }

  async function copyInvite() {
    if (!inviteCode) return
    try {
      await navigator.clipboard.writeText(inviteCode)
      setCopyLabel('Copiato!')
      window.setTimeout(() => setCopyLabel('Copia'), 1400)
    } catch {
      setCopyLabel('Seleziona il codice')
    }
  }

  return <div className="page">
    <PageIntro
      eyebrow="Famiglia"
      title="Utenti"
      description={cloudAuthenticated ? `Membri collegati a ${familyName || 'questa famiglia'} e profili locali.` : 'Ogni persona può avere foto, colore e preferenze personali.'}
      actions={isAdmin && !cloudAuthenticated ? <Button icon={<Plus size={18} />} onClick={openNew}>Nuovo utente</Button> : null}
    />

    {isAdmin && cloudAuthenticated ? <div className="invite-panel">
      <div className="invite-panel__copy"><strong>Invita un membro</strong><span>Genera un codice monouso valido 7 giorni. Sul secondo dispositivo basta registrarsi e scegliere “Usa un codice”.</span></div>
      <Segmented value={inviteRole} onChange={setInviteRole} options={[{ value: 'adult', label: 'Adulto' }, { value: 'child', label: 'Bimbo' }]} />
      <Button size="sm" icon={<UserPlus size={16} />} disabled={inviteBusy} onClick={generateInvite}>{inviteBusy ? 'Creazione…' : 'Genera codice'}</Button>
      {inviteCode ? <><div className="invite-code">{inviteCode}</div><Button variant="ghost" size="sm" icon={<Copy size={15} />} onClick={copyInvite}>{copyLabel}</Button></> : null}
      {inviteError ? <div className="login-error" style={{ width: '100%' }}>{inviteError}</div> : null}
    </div> : null}

    <div className="users-grid">{data.users.map(user => <Card key={user.id} className="user-card">
      <div className="user-card__hero"><Avatar user={user} size="xl" /><div><strong>{user.name}</strong><span>{user.role}</span></div></div>
      <div className="user-card__meta">
        <Badge tone={user.role === 'admin' ? 'violet' : 'neutral'}>{user.role === 'admin' ? <><ShieldCheck size={13} /> Admin</> : user.role}</Badge>
        {user.cloudUserId ? <Badge tone="success"><Cloud size={13} /> Cloud</Badge> : <Badge><KeyRound size={13} /> Profilo locale</Badge>}
      </div>
      {isAdmin ? <div className="user-card__actions"><Button variant="soft" size="sm" onClick={() => setEditing({ ...user })}>Gestisci</Button>{user.id !== authUser?.id && !user.cloudUserId ? <IconButton label="Elimina" onClick={() => deleteUser(user.id)}><Trash2 size={17} /></IconButton> : null}</div> : null}
    </Card>)}</div>

    {!data.users.length ? <Card><EmptyState icon={<UserRound size={30} />} title="Nessun utente" text="Invita o crea il primo profilo familiare." /></Card> : null}

    <Modal open={!!editing} onClose={() => setEditing(null)} title={editing?.id ? 'Gestisci profilo' : 'Nuovo profilo locale'} footer={<div className="modal-actions"><div>{editing?.id && editing.id !== authUser?.id && !editing.cloudUserId ? <Button variant="danger" onClick={() => { deleteUser(editing.id); setEditing(null) }}>Elimina</Button> : null}</div><div className="modal-actions__right"><Button variant="ghost" onClick={() => setEditing(null)}>Annulla</Button><Button onClick={save}>Salva</Button></div></div>}>
      {editing ? <div className="profile-editor"><div className="profile-editor__avatar"><Avatar user={editing} size="xl" /><label className="btn btn--soft btn--sm"><Camera size={16} /> Carica foto<input type="file" accept="image/*" hidden onChange={e => avatarFromFile(e.target.files?.[0])} /></label>{editing.avatarUrl ? <button className="text-link" onClick={() => setEditing({ ...editing, avatarUrl: '' })}>Rimuovi foto</button> : null}</div><div className="form-grid form-grid--2"><Field label="Nome" className="field--wide"><input autoFocus value={editing.name} onChange={e => setEditing({ ...editing, name: e.target.value })} /></Field><Field label="Ruolo"><select value={editing.role} disabled={!!editing.cloudUserId} onChange={e => setEditing({ ...editing, role: e.target.value })}><option value="adulto">Adulto</option><option value="bimbo">Bimbo</option><option value="admin">Admin</option></select></Field><Field label="Colore profilo"><input type="color" value={editing.color} onChange={e => setEditing({ ...editing, color: e.target.value })} /></Field>{!cloudAuthenticated && !editing.cloudUserId ? <Field label="Password" className="field--wide"><input type="password" value={editing.password} onChange={e => setEditing({ ...editing, password: e.target.value })} /></Field> : <div className="callout field--wide">Gli accessi cloud usano email e password personali tramite Supabase. Le password non vengono salvate nei dati della famiglia.</div>}</div></div> : null}
    </Modal>
  </div>
}

